    #[test]
    fn quantile_grouped_inputs_preserve_preparation_admission_and_fallbacks() {
        let range = QueryRequest::Range {
            start_ms: 2000,
            end_ms: 4000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for groups in [0, 1, 4] {
                for delayed in [false, true] {
                    for request in [
                        QueryRequest::Instant { time_ms: 2000 },
                        QueryRequest::Range {
                            start_ms: 2000,
                            end_ms: 2000,
                            step_ms: 1000,
                        },
                        range,
                    ] {
                        for (expression, expected) in [
                            ("quantile(.5,sum by(id)(m_total))", 1),
                            ("quantile(NaN,sum by(id)(m_total))", 1),
                            ("quantile(.5,abs(sum by(id)(m_total)))", 1),
                            ("quantile(.5,sum by(id)(rate(m_total[2s])))", 1),
                            ("quantile(.5,sum by(job)(sum by(job,id)(m_total)))", 2),
                            ("quantile(.5,sum by(id)(m_total @ 2))", 0),
                            ("quantile(.5,sum by(id)(m_total offset 1s))", 1),
                            ("quantile(.5,sum by(id)(timestamp(m_total)))", 0),
                            ("quantile(.5,sum by(id)(m_total*scalar(m_total)))", 0),
                            ("quantile(.5,m_total)", 0),
                            ("topk(1,sum by(id)(m_total))", 1),
                            ("bottomk(1,sum by(id)(m_total))", 1),
                            ("limitk(1,sum by(id)(m_total))", 1),
                            ("limit_ratio(.5,sum by(id)(m_total))", 1),
                            ("topk(0,sum by(id)(m_total))", 1),
                            ("limit_ratio(0,sum by(id)(m_total))", 1),
                            ("topk(1,sum by(id)(m_total @ 2))", 0),
                            ("bottomk(1,sum by(id)(m_total @ 2))", 0),
                            ("limitk(1,sum by(id)(m_total @ 2))", 0),
                            ("limit_ratio(.5,sum by(id)(m_total @ 2))", 0),
                            ("topk(1,sum by(id)(m_total offset 1s))", 1),
                            ("bottomk(1,sum by(id)(m_total offset 1s))", 1),
                            ("limitk(1,sum by(id)(m_total offset 1s))", 1),
                            ("limit_ratio(.5,sum by(id)(m_total offset 1s))", 1),
                            ("topk(1,sum by(id)(timestamp(m_total)))", 0),
                            ("bottomk(1,sum by(id)(timestamp(m_total)))", 0),
                            ("limitk(1,sum by(id)(timestamp(m_total)))", 0),
                            ("limit_ratio(.5,sum by(id)(timestamp(m_total)))", 0),
                            (
                                "last_over_time((limit_ratio(.5,sum by(id)(m_total)))[2s:1s] @ 2)",
                                1,
                            ),
                            (
                                "last_over_time((quantile(.5,sum by(id)(m_total)))[2s:1s] @ 2)",
                                1,
                            ),
                        ] {
                            let engine = Engine::default();
                            let provider = local_grouped_operand_provider(page, groups);
                            let control = Control::default();
                            let mut settings = options(delayed);
                            settings.parser.experimental_functions = expression.contains("limit");
                            let query = engine
                                .compile(expression.as_bytes(), settings, &control)
                                .unwrap();
                            let account = query.execution_accounting();
                            let found = {
                                let header = query.header(request).unwrap();
                                let prepared = Prepared::new(
                                    &query.expression,
                                    &query.preprocessing,
                                    header,
                                    query.options.no_step_subquery_interval_ms,
                                    &control,
                                    &account,
                                )
                                .unwrap();
                                let header = prepared.evaluator_header();
                                prepared.activate(header, &control, &account).unwrap();
                                let options =
                                    query.evaluation_options(header, header.start_ms, &prepared);
                                let bounds = crate::query_bounds::find(
                                    &query.expression,
                                    options,
                                    &prepared,
                                    &control,
                                    &account,
                                )
                                .unwrap();
                                let scope = provider.open(bounds, &control).unwrap();
                                let catalog = Catalog::new(
                                    &scope,
                                    &query.expression,
                                    &prepared,
                                    options,
                                    query.options.no_step_subquery_interval_ms,
                                    &control,
                                    &account,
                                )
                                .unwrap();
                                let rosters = query
                                    .prepare_rosters(
                                        &catalog,
                                        &prepared,
                                        bounds,
                                        &control,
                                        &account,
                                        &mut Annotations::default(),
                                    )
                                    .unwrap();
                                (0..query.expression.arena.nodes.len())
                                    .filter(|&index| {
                                        let node = NodeId(index);
                                        if let Some(plan) = rosters.group_replay(node) {
                                            assert!(!plan.has_completion());
                                        }
                                        if rosters.group_selector(node).is_some() {
                                            assert_eq!(
                                                rosters.group_replay(node).is_some(),
                                                rosters.groups(node).unwrap().len() > 1
                                            );
                                            true
                                        } else {
                                            false
                                        }
                                    })
                                    .count()
                            };
                            provider.assert_closed();
                            account.snapshot().assert_memory_released();
                            drop((account, query));
                            engine.accounting.snapshot().assert_memory_released();
                            assert_eq!(
                                found,
                                if groups == 0 { 0 } else { expected },
                                "{expression} {request:?} {groups} {delayed}"
                            );
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn shared_proof_owner_preserves_group_and_schedule_identities() {
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for (expression, scheduled, groups, filtering) in [
                    ("counter_total", true, 0, 0),
                    ("abs(counter_total)", true, 0, 0),
                    ("counter_total*2", true, 0, 0),
                    (
                        "label_join(counter_total,\"row\",\"/\",\"instance\")",
                        true,
                        0,
                        0,
                    ),
                    (
                        "label_replace(counter_total,\"row\",\"$1\",\"instance\",\"(.*)\")",
                        true,
                        0,
                        0,
                    ),
                    ("abs(sum by(job)(counter_total))", false, 1, 0),
                    ("topk(1,sum by(job)(counter_total))", false, 1, 0),
                    ("quantile(.5,sum by(job)(counter_total))", false, 1, 0),
                    (
                        "abs(sum by(job)(sum by(instance)(counter_total)))",
                        false,
                        2,
                        1,
                    ),
                    ("abs(sum by(instance)(counter_total))", false, 1, 1),
                    ("abs(sum by(job)(timestamp(counter_total)))", false, 0, 0),
                ] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let provider = FixtureProvider::new(4, page, 2);
                    let query = engine
                        .compile(expression.as_bytes(), options(delayed), &control)
                        .unwrap();
                    let account = query.execution_accounting();
                    {
                        let header = query
                            .header(QueryRequest::Range {
                                start_ms: 1000,
                                end_ms: 3000,
                                step_ms: 1000,
                            })
                            .unwrap();
                        let prepared = Prepared::new(
                            &query.expression,
                            &query.preprocessing,
                            header,
                            query.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let header = prepared.evaluator_header();
                        prepared.activate(header, &control, &account).unwrap();
                        let evaluation =
                            query.evaluation_options(header, header.start_ms, &prepared);
                        let bounds = crate::query_bounds::find(
                            &query.expression,
                            evaluation,
                            &prepared,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let scope = provider.open(bounds, &control).unwrap();
                        let catalog = Catalog::new(
                            &scope,
                            &query.expression,
                            &prepared,
                            evaluation,
                            query.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let rosters = query
                            .prepare_rosters(
                                &catalog,
                                &prepared,
                                bounds,
                                &control,
                                &account,
                                &mut Annotations::default(),
                            )
                            .unwrap();
                        assert_eq!(
                            rosters.scheduled_selector(query.expression.root).is_some(),
                            scheduled,
                            "{expression}"
                        );
                        let (mut group_count, mut filter_count) = (0, 0);
                        for index in 0..query.expression.arena.nodes.len() {
                            let node = NodeId(index);
                            if rosters.scheduled_selector(node).is_some() {
                                assert!(!matches!(
                                    query.expression.arena[node].expression,
                                    Expr::Aggregate { .. }
                                ));
                                assert!(rosters.group_selector(node).is_none());
                            }
                            if let Some(selector) = rosters.group_selector(node) {
                                assert!(rosters.scheduled_selector(node).is_none());
                                assert!(matches!(
                                    query.expression.arena[selector].expression,
                                    Expr::Selector(_)
                                ));
                                assert_eq!(
                                    rosters.group_replay(node).is_some(),
                                    rosters.groups(node).unwrap().len() > 1
                                );
                                group_count += 1;
                            }
                            if let Some(plan) = rosters.group_replay(node) {
                                assert!(!plan.has_completion());
                                filter_count += 1;
                            }
                        }
                        assert_eq!(
                            (group_count, filter_count),
                            (groups, filtering),
                            "{expression}"
                        );
                        println!(
                            "shared-proof-identities expression={expression:?} page={page} delayed={delayed} scheduled={scheduled} groups={group_count} filtering={filter_count}"
                        );
                    }
                    provider.assert_closed();
                    account.snapshot().assert_memory_released();
                    drop((account, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn completed_single_group_join_values_keep_results_and_read_growth() {
        let (mut complete, mut growth) = (0, [0_u64; 2]);
        for groups in [4, 16] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    for reverse in [false, true] {
                        let many = "sum by(instance)(counter_total)";
                        let one = "sum(counter_total)";
                        let (left, right, modifier) = if reverse {
                            (one, many, "group_right()")
                        } else {
                            (many, one, "group_left()")
                        };
                        let ratio = format!("{left}/on(){modifier} {right}");
                        for (shape, expression) in [
                            ratio.clone(),
                            format!("abs(({left})/on(){modifier} ({right}))"),
                            format!("sum({ratio})"),
                        ]
                        .iter()
                        .enumerate()
                        {
                            for request in [
                                QueryRequest::Instant { time_ms: 2000 },
                                QueryRequest::Range {
                                    start_ms: 2000,
                                    end_ms: 2000,
                                    step_ms: 1000,
                                },
                                QueryRequest::Range {
                                    start_ms: 1000,
                                    end_ms: 3000,
                                    step_ms: 1000,
                                },
                            ] {
                                let engine = Engine::default();
                                let control = Control::default();
                                let provider = FixtureProvider::new(4, page, groups);
                                let query = engine
                                    .compile(expression.as_bytes(), options(delayed), &control)
                                    .unwrap();
                                let report = query.collect_reported(&provider, request, &control);
                                let result = report.result.as_ref().unwrap();
                                let times = if matches!(
                                    request,
                                    QueryRequest::Range { start_ms: 1000, .. }
                                ) {
                                    &[1000_i64, 2000, 3000][..]
                                } else {
                                    &[2000_i64][..]
                                };
                                let rows = if shape == 2 { 1 } else { groups };
                                let value = if reverse {
                                    groups as f64
                                } else {
                                    1.0 / groups as f64
                                } * if shape == 2 { groups as f64 } else { 1.0 };
                                assert!(result.scalar.is_none() && report.annotations.is_empty());
                                assert_eq!(result.series.len(), rows);
                                assert_eq!(
                                    report.observations.output_samples,
                                    (rows * times.len()) as u64
                                );
                                let mut seen = vec![false; groups];
                                for row in &result.series {
                                    if shape == 2 {
                                        assert!(row.labels.0.is_empty());
                                    } else {
                                        assert_eq!(row.labels.0.len(), 1);
                                        assert_eq!(&*row.labels.0[0].name, b"instance");
                                        let ordinal: usize =
                                            std::str::from_utf8(&row.labels.0[0].value)
                                                .unwrap()
                                                .parse()
                                                .unwrap();
                                        assert!(ordinal < groups && !seen[ordinal]);
                                        seen[ordinal] = true;
                                    }
                                    assert_eq!(row.points.len(), times.len());
                                    for (point, &time_ms) in row.points.iter().zip(times) {
                                        assert_eq!(point.time_ms, time_ms);
                                        let OwnedValue::Float(actual) = &point.value else {
                                            panic!("expected completed float ratio");
                                        };
                                        assert_eq!(actual.to_bits(), value.to_bits());
                                    }
                                }
                                if shape != 2 {
                                    assert!(seen.into_iter().all(|value| value));
                                }
                                let fetched = report.observations.samples_fetched;
                                assert_eq!(
                                    fetched,
                                    provider.series[0]
                                        .source
                                        .counters
                                        .samples_returned
                                        .load(Ordering::Relaxed)
                                        as u64
                                );
                                if shape == 0
                                    && !reverse
                                    && !delayed
                                    && page == 1
                                    && matches!(request, QueryRequest::Instant { .. })
                                {
                                    growth[usize::from(groups == 16)] = fetched;
                                }
                                println!(
                                    "single-group-result groups={groups} page={page} delayed={delayed} reverse={reverse} shape={shape} request={request:?} fetched={fetched} work={}",
                                    report.observations.work
                                );
                                provider.assert_closed();
                                drop((report, query));
                                engine.accounting.snapshot().assert_memory_released();
                                complete += 1;
                            }
                        }
                    }
                }
            }
        }
        assert_eq!(complete, 216);
        println!("single-group-complete results={complete}");
        println!(
            "single-group-growth groups4={} groups16={}",
            growth[0], growth[1]
        );
        assert!(growth[0] > 0 && growth[1] > 0);
        assert!(
            growth[1] <= growth[0].saturating_mul(8),
            "completed singleton joins must avoid quadratic raw reads"
        );
    }

    #[test]
    fn derived_float_kind_preserves_post_preparation_read_failures() {
        let request = QueryRequest::Range {
            start_ms: 2000,
            end_ms: 3000,
            step_ms: 1000,
        };
        let acquisitions = |input: &FixtureProvider| {
            input.series[0]
                .source
                .counters
                .opened
                .load(Ordering::Relaxed)
        };
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                let engine = Engine::default();
                let control = Control::default();
                let compiled = engine
                    .compile(
                        b"sum_over_time((counter_total or counter_total)[2s:1s])",
                        options(delayed),
                        &control,
                    )
                    .unwrap();
                let calibration = FixtureProvider::new(3, page, 1);
                let (rows, prepared) =
                    float_map_join_preparation(&compiled, &calibration, request, &control);
                assert_eq!(rows, 1);
                let input = FixtureProvider::new(3, page, 1);
                let report = compiled.collect_reported(&input, request, &control);
                let output = report.result.as_ref().unwrap();
                assert_eq!(output.series.len(), 1);
                assert_eq!(
                    output.series[0]
                        .labels
                        .0
                        .iter()
                        .map(|label| (label.name.to_vec(), label.value.to_vec()))
                        .collect::<Vec<_>>(),
                    [
                        (b"instance".to_vec(), b"0".to_vec()),
                        (b"job".to_vec(), b"worker".to_vec())
                    ]
                );
                assert_eq!(output.series[0].points.len(), 2);
                for (point, (time, value)) in output.series[0]
                    .points
                    .iter()
                    .zip([(2000, 3.0_f64), (3000, 5.0_f64)])
                {
                    assert_eq!(point.time_ms, time);
                    assert_eq!(float_bits(point), value.to_bits());
                }
                assert!(report.annotations.is_empty());
                let last = acquisitions(&input);
                input.assert_closed();
                drop(report);

                let first_input = FixtureProvider::new(3, page, 1);
                let mut first_sink = RecordingSink {
                    fail_after: Some(1),
                    ..RecordingSink::default()
                };
                let report =
                    compiled.execute_reported(&first_input, request, &control, &mut first_sink);
                assert!(matches!(&report.result, Err(ExecutionError::Sink(bytes))
                    if &**bytes == b"sink failure"));
                let first = acquisitions(&first_input);
                assert!(prepared[0] < first && first < last);
                first_input.assert_closed();
                report.assert_retained_callback_error_memory();
                drop(report);

                // Fail every actually required read after the frozen roster is prepared.
                for acquisition in prepared[0] + 1..=last {
                    let mut input = FixtureProvider::new(3, page, 1);
                    input.series[0].source.fail_acquisition = Some(acquisition);
                    let mut sink = RecordingSink::default();
                    let report = compiled.execute_reported(&input, request, &control, &mut sink);
                    assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                        EvaluationError::Storage(StorageError::Provider(bytes))))
                        if &**bytes == b"injected page failure"));
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(acquisitions(&input), acquisition);
                    assert_eq!(sink.chunks, usize::from(acquisition > first));
                    assert_eq!(report.observations.output_samples, sink.chunks as u64);
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    input.assert_closed();
                }
                println!(
                    "{{\"derived_kind_read_phase\":\"post-preparation\",\"page\":{page},\"delayed\":{delayed},\"preparation\":{},\"first\":{first},\"last\":{last},\"faults\":{}}}",
                    prepared[0],
                    last - prepared[0],
                );
                drop(compiled);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn completed_single_group_join_values_preserve_actual_read_phases() {
        let acquisitions = |provider: &FixtureProvider| {
            provider
                .series
                .iter()
                .map(|series| series.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        for page in [1, 17, 1024] {
            for reverse in [false, true] {
                let engine = Engine::default();
                let expression = if reverse {
                    "sum(b)/on()group_right() a"
                } else {
                    "a/on()group_left() sum(b)"
                };
                let compiled = engine
                    .compile(expression.as_bytes(), options(false), &Control::default())
                    .unwrap();
                let mut landmarks: Vec<Vec<usize>> = Vec::new();
                for fault in ["none", "cold", "omitted", "many", "next", "cancel"] {
                    let control = Control::default();
                    let mut provider = float_map_join_provider(page);
                    for (position, series) in provider.series.iter_mut().enumerate() {
                        series.source.sample = if position < 4 {
                            |index| crate::value::Sample {
                                time_ms: (index as i64 + 1) * 1000,
                                start_time_ms: 0,
                                value: crate::value::SampleValue::Float(
                                    ((index + 1) * (index + 1)) as f64,
                                ),
                            }
                        } else {
                            |index| crate::value::Sample {
                                time_ms: (index as i64 + 1) * 1000,
                                start_time_ms: 0,
                                value: crate::value::SampleValue::Float((index + 1) as f64),
                            }
                        };
                    }
                    if fault != "none" && fault != "cancel" {
                        let (target, phase) = match fault {
                            "cold" => (4, 0),
                            "omitted" => (4, 1),
                            "many" => (0, 1),
                            "next" => (4, 2),
                            _ => unreachable!(),
                        };
                        provider.series[target].source.fail_acquisition =
                            Some(landmarks[phase][target] + 1);
                    }
                    let account = compiled.execution_accounting();
                    {
                        let prepared = Prepared::new(
                            &compiled.expression,
                            &compiled.preprocessing,
                            compiled
                                .header(QueryRequest::Range {
                                    start_ms: 1000,
                                    end_ms: 3000,
                                    step_ms: 1000,
                                })
                                .unwrap(),
                            compiled.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let header = prepared.evaluator_header();
                        prepared.activate(header, &control, &account).unwrap();
                        let initial = compiled.evaluation_options(header, 1000, &prepared);
                        let bounds = crate::query_bounds::find(
                            &compiled.expression,
                            initial,
                            &prepared,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let scope = provider.open(bounds, &control).unwrap();
                        let catalog = Catalog::new(
                            &scope,
                            &compiled.expression,
                            &prepared,
                            initial,
                            compiled.options.no_step_subquery_interval_ms,
                            &control,
                            &account,
                        )
                        .unwrap();
                        let rosters = compiled
                            .prepare_rosters(
                                &catalog,
                                &prepared,
                                bounds,
                                &control,
                                &account,
                                &mut Annotations::default(),
                            )
                            .unwrap();
                        // Mirror the actual preparation-to-final value boundary.
                        prepared.range_folds.clear(&control, &account).unwrap();
                        assert_eq!(prepared.range_folds.completed_aggregates(), 0);
                        let root = compiled.expression.root;
                        let (rows, sources) = rosters.ordered(root).unwrap();
                        let ordinals = [0, 1].map(|position| {
                            let bindings = &sources[rows[position].sources.clone()];
                            assert_eq!(bindings.len(), 1);
                            bindings[0]
                        });
                        if fault == "none" {
                            landmarks.push(acquisitions(&provider));
                        } else {
                            assert_eq!(acquisitions(&provider), landmarks[0]);
                        }
                        for (phase, (time, step, ordinal)) in [
                            (1000, 0, ordinals[0]),
                            (1000, 0, ordinals[1]),
                            (2000, 1, ordinals[1]),
                        ]
                        .into_iter()
                        .enumerate()
                        {
                            let before = acquisitions(&provider);
                            if fault == "cancel" && phase == 1 {
                                control.cancellation.cancel();
                            }
                            let mut machine = Machine::new(
                                &catalog,
                                &compiled.expression,
                                root,
                                compiled.evaluation_options(header, time, &prepared),
                                &control,
                                &account,
                                EvaluationMetadata {
                                    prepared: &prepared,
                                    rosters: &rosters,
                                    timestamp_selectors: &compiled.timestamp_selectors,
                                    data_bounds: bounds,
                                    annotations: None,
                                    binary_preparation: None,
                                    histogram_preparation: None,
                                    info_preparation: None,
                                    count_preparation: None,
                                },
                            );
                            machine.restrict_one(ordinal);
                            machine.bypass_root_order();
                            machine.set_step_index(step);
                            let result = machine.next();
                            let failed = match fault {
                                "cold" => phase == 0,
                                "many" | "cancel" => phase == 1,
                                "next" => phase == 2,
                                _ => false,
                            };
                            if failed {
                                if fault == "cancel" {
                                    assert!(matches!(
                                        result,
                                        Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                    ));
                                    assert_eq!(acquisitions(&provider), before);
                                } else {
                                    assert!(
                                        matches!(&result, Err(EvaluationError::Storage(StorageError::Provider(bytes))) if &**bytes == b"injected page failure")
                                    );
                                }
                                drop(result);
                                drop(machine);
                                if fault == "cold" || fault == "next" {
                                    assert_eq!(prepared.range_folds.completed_aggregates(), 0);
                                }
                                break;
                            }
                            let sample = result.unwrap().unwrap();
                            assert_eq!(sample.ordinal, ordinal);
                            assert_eq!(sample.source_time_ms, time);
                            assert_eq!(sample.source_start_time_ms, 0);
                            let descriptor = &rows[usize::from(phase != 0)];
                            let labels = |labels: &crate::result::OwnedLabels| {
                                labels
                                    .0
                                    .iter()
                                    .map(|label| (label.name.to_vec(), label.value.to_vec()))
                                    .collect::<Vec<_>>()
                            };
                            assert_eq!(labels(&sample.labels), labels(&descriptor.labels));
                            let OwnedValue::Float(value) = &sample.value else {
                                panic!("singleton ratio")
                            };
                            let expected = if reverse {
                                4.0 / (time / 1000) as f64
                            } else {
                                (time / 1000) as f64 / 4.0
                            };
                            assert_eq!(value.to_bits(), expected.to_bits());
                            drop(sample);
                            assert!(machine.next().unwrap().is_none());
                            drop(machine);
                            assert_eq!(prepared.range_folds.completed_aggregates(), 1);
                            let after = acquisitions(&provider);
                            if phase == 1 {
                                assert_eq!(
                                    &after[4..],
                                    &before[4..],
                                    "completed singleton must not be reacquired"
                                );
                                assert!(
                                    after[..4]
                                        .iter()
                                        .zip(&before[..4])
                                        .any(|(now, before)| now > before)
                                );
                            } else {
                                assert!(
                                    after[4..]
                                        .iter()
                                        .zip(&before[4..])
                                        .all(|(now, before)| now > before)
                                );
                            }
                            if fault == "none" {
                                landmarks.push(after);
                            }
                            println!(
                                "single-group-read-phase page={page} reverse={reverse} fault={fault} phase={phase}"
                            );
                            if fault == "omitted" && phase == 1 {
                                break;
                            }
                        }
                    }
                    provider.assert_closed();
                    account.snapshot().assert_memory_released();
                    drop(account);
                }
                drop(compiled);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn completed_single_group_values_keep_one_pass_native_and_absent_fallbacks() {
        for page in [1, 17, 1024] {
            for (expression, kind) in [
                ("sum(b)", "sum"),
                ("abs(sum(b))", "sum"),
                ("sum(sum by(instance)(b))", "sum"),
                ("topk(1,sum by(instance)(b))", "selection"),
                ("sum(b)/on()sum(b)", "single"),
                ("a*on()group_left()sum(b)", "native"),
                ("a*on()group_left()sum(b)", "mixed"),
                ("a/on()group_left()sum(b)", "transition"),
            ] {
                let engine = Engine::default();
                let control = Control::default();
                let compiled = engine
                    .compile(expression.as_bytes(), options(false), &control)
                    .unwrap();
                let mut provider = float_map_join_provider(page);
                for (position, series) in provider.series.iter_mut().enumerate().skip(4) {
                    if kind == "native" || kind == "mixed" && position.is_multiple_of(2) {
                        series.source.sample = |index| crate::value::Sample {
                            time_ms: (index as i64 + 1) * 1000,
                            start_time_ms: 0,
                            value: crate::value::SampleValue::FloatHistogram(
                                crate::histogram::FloatHistogram {
                                    count: 1.0,
                                    sum: 2.0,
                                    zero_count: 1.0,
                                    ..Default::default()
                                },
                            ),
                        };
                    } else if kind == "transition" {
                        series.source.sample = |index| crate::value::Sample {
                            time_ms: (index as i64 + 1) * 1000,
                            start_time_ms: 0,
                            value: crate::value::SampleValue::Float(if index == 1 {
                                2.0
                            } else {
                                f64::from_bits(crate::value::STALE_NAN_BITS)
                            }),
                        };
                    }
                }
                let account = compiled.execution_accounting();
                {
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        compiled
                            .header(QueryRequest::Range {
                                start_ms: 1000,
                                end_ms: 3000,
                                step_ms: 1000,
                            })
                            .unwrap(),
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let initial = compiled.evaluation_options(header, 1000, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        initial,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        initial,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    prepared.range_folds.clear(&control, &account).unwrap();
                    assert_eq!(prepared.range_folds.completed_aggregates(), 0);
                    for step in 0..3 {
                        let time = (step + 1) * 1000;
                        let mut annotations = AnnotationBuilder::new(&account);
                        let mut machine = Machine::new(
                            &catalog,
                            &compiled.expression,
                            compiled.expression.root,
                            compiled.evaluation_options(header, time, &prepared),
                            &control,
                            &account,
                            EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &compiled.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: Some(&mut annotations),
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            },
                        );
                        machine.set_step_index(step);
                        let mut count = 0;
                        while let Some(sample) = machine.next().unwrap() {
                            assert_eq!(sample.source_time_ms, time);
                            if kind == "native" {
                                let OwnedValue::Histogram(value) = &sample.value else {
                                    panic!("native singleton fallback")
                                };
                                assert_eq!(
                                    value.as_ref().count.to_bits(),
                                    (4.0 * (step + 1) as f64).to_bits()
                                );
                                assert_eq!(
                                    value.as_ref().sum.to_bits(),
                                    (8.0 * (step + 1) as f64).to_bits()
                                );
                            } else {
                                let OwnedValue::Float(value) = &sample.value else {
                                    panic!("float singleton fallback")
                                };
                                let expected = match kind {
                                    "sum" => 4.0 * (step + 1) as f64,
                                    "selection" => (step + 1) as f64,
                                    "single" => 1.0,
                                    "transition" => 0.25,
                                    _ => unreachable!(),
                                };
                                assert_eq!(value.to_bits(), expected.to_bits());
                            }
                            count += 1;
                        }
                        drop(machine);
                        let expected_rows = match kind {
                            "native" => 4,
                            "mixed" => 0,
                            "transition" if step == 1 => 4,
                            "transition" => 0,
                            _ => 1,
                        };
                        assert_eq!(count, expected_rows, "{expression} {kind} {time}");
                        assert_eq!(
                            prepared.range_folds.completed_aggregates(),
                            usize::from(kind == "transition" && step == 1)
                        );
                    }
                }
                provider.assert_closed();
                account.snapshot().assert_memory_released();
                drop((account, compiled));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn empty_group_owners_keep_productive_singleton_joins_and_later_rows() {
        fn late(index: usize) -> crate::value::Sample {
            let tick = (index + 1) as f64;
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(if index < 2 {
                    f64::from_bits(0x7ff0_0000_0000_0002)
                } else {
                    100.0 + tick * tick
                }),
            }
        }
        for window in [false, true] {
            let m = if window {
                "rate(m_total[2s])"
            } else {
                "m_total"
            };
            let n = if window {
                "rate(n_total[2s])"
            } else {
                "n_total"
            };
            for reverse in [false, true] {
                let expression = if reverse {
                    format!("sum by(job)({n}) / on(job) group_right sum by(job,id)({m})")
                } else {
                    format!("sum by(job,id)({m}) / on(job) group_left sum by(job)({n})")
                };
                let expression = format!("abs({expression})");
                for page in [1, 17, 1024] {
                    for later in [false, true] {
                        let mut growth = Vec::new();
                        for groups in [2_usize, 4, 8, 16] {
                            let engine = Engine::default();
                            let control = Control::default();
                            let mut provider = local_grouped_operand_provider(page, groups);
                            if later {
                                for row in &mut provider.series[..groups * 2] {
                                    row.source.sample = late;
                                }
                            }
                            let query = engine
                                .compile(expression.as_bytes(), options(false), &control)
                                .unwrap();
                            let request = QueryRequest::Range {
                                start_ms: 2000,
                                end_ms: 4000,
                                step_ms: 1000,
                            };
                            let (rows, _, pairs) = float_map_join_preparation_with_discovery(
                                &query, &provider, request, &control,
                            );
                            assert_eq!((rows, pairs), (groups, 1));
                            let fetched_before: usize = provider
                                .series
                                .iter()
                                .map(|row| {
                                    row.source.counters.samples_returned.load(Ordering::Relaxed)
                                })
                                .sum();
                            let report = query.collect_reported(&provider, request, &control);
                            let result = report.result.as_ref().unwrap();
                            assert!(report.annotations.is_empty());
                            assert_eq!(result.series.len(), groups);
                            let first = if later { if window { 4 } else { 3 } } else { 2 };
                            for (identity, row) in result.series.iter().enumerate() {
                                assert_eq!(row.labels.0.len(), 2);
                                assert_eq!(&*row.labels.0[0].name, b"id");
                                assert_eq!(
                                    &*row.labels.0[0].value,
                                    format!("{identity:06}").as_bytes()
                                );
                                assert_eq!(
                                    (&*row.labels.0[1].name, &*row.labels.0[1].value),
                                    (&b"job"[..], &b"worker"[..])
                                );
                                assert_eq!(row.points.len(), 5 - first);
                                for (offset, point) in row.points.iter().enumerate() {
                                    let tick = (first + offset) as f64;
                                    let scale = if later {
                                        2.0
                                    } else if identity.is_multiple_of(2) {
                                        6.0
                                    } else {
                                        24.0
                                    };
                                    let left = scale
                                        * if window {
                                            2.0 * tick - 1.0
                                        } else {
                                            100.0 + tick * tick
                                        };
                                    let right = 4.0
                                        * groups as f64
                                        * if window { 1.0 } else { 100.0 + tick };
                                    let expected =
                                        if reverse { right / left } else { left / right };
                                    assert_eq!(point.time_ms, (first + offset) as i64 * 1000);
                                    assert_eq!(float_bits(point), expected.to_bits());
                                }
                            }
                            assert_eq!(
                                report.observations.output_samples,
                                (groups * (5 - first)) as u64
                            );
                            let fetched: usize = provider
                                .series
                                .iter()
                                .map(|row| {
                                    assert!(row.source.counters.peak.load(Ordering::Relaxed) <= 1);
                                    row.source.counters.samples_returned.load(Ordering::Relaxed)
                                })
                                .sum();
                            assert_eq!(
                                report.observations.samples_fetched,
                                (fetched - fetched_before) as u64
                            );
                            println!(
                                "empty-group-singleton window={window} reverse={reverse} page={page} later={later} groups={groups} work={} fetched={}",
                                report.observations.work, report.observations.samples_fetched
                            );
                            growth.push((
                                report.observations.work,
                                report.observations.samples_fetched,
                            ));
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                        // Excluded name and clock scopes retain the ordinary reduction path.
                        assert!(growth[3].0 <= growth[1].0 * 32 && growth[3].1 <= growth[1].1 * 32);
                    }
                }
            }
        }
    }

    #[test]
    fn empty_group_owners_keep_opposite_input_and_parameter_failures() {
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for expression in [
                    "sum by(job,id)(m_total{missing=\"yes\"}) / on(job) group_left sum by(job)(n_total)",
                    "sum by(job)(n_total) / on(job) group_right sum by(job,id)(m_total{missing=\"yes\"})",
                    "topk(scalar(sum(n_total)),sum by(job,id)(m_total{missing=\"yes\"}))",
                    "topk(NaN,sum by(job,id)(m_total{missing=\"yes\"}) / on(job) group_left sum by(job)(n_total))",
                ] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut provider = local_grouped_operand_provider(page, 4);
                    provider.series[8].source.fail_acquisition = Some(1);
                    let query = engine
                        .compile(expression.as_bytes(), options(delayed), &control)
                        .unwrap();
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Range {
                            start_ms: 2000,
                            end_ms: 4000,
                            step_ms: 1000,
                        },
                        &control,
                    );
                    assert!(
                        matches!(&report.result, Err(ExecutionError::Evaluation(
                        EvaluationError::Storage(StorageError::Provider(bytes))))
                        if &**bytes == b"injected page failure"),
                        "{expression}: {:?}",
                        report.result
                    );
                    assert!(
                        provider.series[..8].iter().all(|row| row
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed)
                            == 0)
                    );
                    assert_eq!(
                        provider.series[8]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        1
                    );
                    println!(
                        "empty-group-required expression={expression:?} page={page} delayed={delayed} target=8 acquisition=1"
                    );
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn quantile_grouped_inputs_keep_parameter_errors_and_invalid_q_body_reads() {
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for parameter in ["scalar(n_total)", "NaN", "Inf", "-Inf"] {
                    let mut provider = local_grouped_operand_provider(page, 4);
                    if parameter.starts_with("scalar") {
                        for row in &mut provider.series {
                            row.source.fail_acquisition = Some(1);
                        }
                    } else {
                        provider.series[7].source.fail_acquisition = Some(1);
                    }
                    let engine = Engine::default();
                    let control = Control::default();
                    let expression = format!("quantile({parameter},sum by(job,id)(m_total))");
                    let query = engine
                        .compile(expression.as_bytes(), options(delayed), &control)
                        .unwrap();
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 2000 },
                        &control,
                    );
                    assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                        EvaluationError::Storage(StorageError::Provider(bytes))))
                        if &**bytes == b"injected page failure"));
                    if parameter.starts_with("scalar") {
                        assert!(provider.series[..8].iter().all(|row| {
                            row.source.counters.opened.load(Ordering::Relaxed) == 0
                        }));
                        assert!(provider.series[8..].iter().any(|row| {
                            row.source.counters.opened.load(Ordering::Relaxed) == 1
                        }));
                    } else {
                        assert_eq!(
                            provider.series[7]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            1,
                            "invalid quantile still reads the late body member"
                        );
                    }
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn selection_grouped_inputs_keep_parameter_and_late_body_error_priority() {
        for operator in ["topk", "bottomk", "limitk", "limit_ratio"] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    for parameter in [
                        "scalar(n_total)",
                        "0",
                        "0.5",
                        "-0.5",
                        "NaN",
                        "Inf",
                        "-Inf",
                        "9223372036854774784",
                        "-9223372036854775808",
                    ] {
                        let mut provider = local_grouped_operand_provider(page, 4);
                        let parameter_fault = parameter.starts_with("scalar");
                        if parameter_fault {
                            for row in &mut provider.series {
                                row.source.fail_acquisition = Some(1);
                            }
                        } else {
                            provider.series[7].source.fail_acquisition = Some(1);
                        }
                        let engine = Engine::default();
                        let control = Control::default();
                        let mut settings = options(delayed);
                        settings.parser.experimental_functions = operator.starts_with("limit");
                        let expression = format!("{operator}({parameter},sum by(job,id)(m_total))");
                        let query = engine
                            .compile(expression.as_bytes(), settings, &control)
                            .unwrap();
                        let report = query.collect_reported(
                            &provider,
                            QueryRequest::Instant { time_ms: 2000 },
                            &control,
                        );
                        assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                            EvaluationError::Storage(StorageError::Provider(bytes))))
                            if &**bytes == b"injected page failure"));
                        if parameter_fault {
                            assert!(provider.series[..8].iter().all(|row| {
                                row.source.counters.opened.load(Ordering::Relaxed) == 0
                            }));
                            assert!(provider.series[8..].iter().any(|row| {
                                row.source.counters.opened.load(Ordering::Relaxed) == 1
                            }));
                        } else {
                            assert_eq!(
                                provider.series[7]
                                    .source
                                    .counters
                                    .opened
                                    .load(Ordering::Relaxed),
                                1,
                                "{operator}({parameter}) must prepare the late body member"
                            );
                        }
                        provider.assert_closed();
                        drop((report, query));
                        engine.accounting.snapshot().assert_memory_released();
                    }
                }
            }
        }
    }

    #[test]
    fn selection_grouped_inputs_keep_nested_parameter_clock_and_error_order() {
        for (operator, parameter, winners) in [
            ("topk", "2", 2),
            ("bottomk", "2", 2),
            ("limitk", "2", 2),
            ("limit_ratio", "1", 4),
        ] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    for (points, request) in [
                        (1, QueryRequest::Instant { time_ms: 2000 }),
                        (
                            1,
                            QueryRequest::Range {
                                start_ms: 2000,
                                end_ms: 2000,
                                step_ms: 1000,
                            },
                        ),
                        (
                            3,
                            QueryRequest::Range {
                                start_ms: 2000,
                                end_ms: 4000,
                                step_ms: 1000,
                            },
                        ),
                    ] {
                        for fault in [false, true] {
                            let engine = Engine::default();
                            let control = Control::default();
                            let mut provider = local_grouped_operand_provider(page, 4);
                            if fault {
                                provider.series[7].source.fail_acquisition = Some(1);
                                for row in &mut provider.series[8..] {
                                    row.source.fail_acquisition = Some(1);
                                }
                            }
                            let expression = format!(
                                "sum(topk(scalar(count({operator}({parameter},sum by(job,id)(m_total)))),sum by(job,id)(n_total)))"
                            );
                            let mut settings = options(delayed);
                            settings.parser.experimental_functions = operator.starts_with("limit");
                            let query = engine
                                .compile(expression.as_bytes(), settings, &control)
                                .unwrap();
                            let report = query.collect_reported(&provider, request, &control);
                            if fault {
                                assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                                    EvaluationError::Storage(StorageError::Provider(bytes))))
                                    if &**bytes == b"injected page failure"));
                                assert_eq!(
                                    provider.series[7]
                                        .source
                                        .counters
                                        .opened
                                        .load(Ordering::Relaxed),
                                    1
                                );
                                assert!(provider.series[8..].iter().all(|row| {
                                    row.source.counters.opened.load(Ordering::Relaxed) == 0
                                }));
                            } else {
                                let result = report.result.as_ref().unwrap();
                                assert!(report.annotations.is_empty());
                                assert_eq!(result.series.len(), 1);
                                let row = &result.series[0];
                                assert!(row.labels.0.is_empty());
                                assert_eq!(row.points.len(), points);
                                for (tick, point) in row.points.iter().enumerate() {
                                    let expected = (winners * 4) as f64 * (102.0 + tick as f64);
                                    assert_eq!(point.time_ms, (tick as i64 + 2) * 1000);
                                    assert_eq!(float_bits(point), expected.to_bits());
                                }
                                assert_eq!(report.observations.output_samples, points as u64);
                            }
                            provider.assert_closed();
                            drop((report, query));
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
        }
    }

    fn ordered_binary_provider(page: usize, count: usize) -> FixtureProvider {
        fn point<const SCALE: u32>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float((index + 1) as f64 * f64::from(SCALE)),
            }
        }
        let mut provider = FixtureProvider::new(3, page, count * 2);
        provider.filter_selectors = true;
        for (position, series) in provider.series.iter_mut().enumerate() {
            let right = position >= count;
            let identity = count - 1 - position % count;
            series.labels = vec![
                (
                    b"__name__".to_vec(),
                    if right { b"n" } else { b"m" }.to_vec(),
                ),
                (b"id".to_vec(), format!("{identity:06}").into_bytes()),
                (b"job".to_vec(), b"worker".to_vec()),
            ];
            series.source.sample = if right {
                point::<4>
            } else if identity.is_multiple_of(2) {
                point::<2>
            } else {
                point::<8>
            };
            series.source.counters = Default::default();
        }
        provider
    }

    #[test]
    fn ordered_binary_consumers_check_complete_results_before_bounded_reads() {
        let mut growth = Vec::new();
        let mut complete = 0;
        for (expression, grouped) in [
            ("m+n", false),
            ("m>n", false),
            ("m>bool n", false),
            ("abs(m+n)", false),
            ("sum by(job)(m+n)", true),
        ] {
            for delayed in [false, true] {
                for page in [17, 1024] {
                    for count in [2, 4, 8, 16] {
                        let engine = Engine::default();
                        let control = Control::default();
                        let provider = ordered_binary_provider(page, count);
                        let query = engine
                            .compile(
                                expression.as_bytes(),
                                EngineOptions {
                                    delayed_name_removal: delayed,
                                    ..EngineOptions::default()
                                },
                                &control,
                            )
                            .unwrap();
                        let report = query.collect_reported(
                            &provider,
                            QueryRequest::Range {
                                start_ms: 1000,
                                end_ms: 3000,
                                step_ms: 1000,
                            },
                            &control,
                        );
                        let result = report.result.as_ref().unwrap();
                        assert!(report.annotations.is_empty());
                        let filtered = expression == "m>n";
                        let boolean = expression == "m>bool n";
                        let rows = if grouped {
                            1
                        } else if filtered {
                            count / 2
                        } else {
                            count
                        };
                        assert_eq!(result.series.len(), rows);
                        for (position, row) in result.series.iter().enumerate() {
                            let identity = if filtered { position * 2 + 1 } else { position };
                            let labels: Vec<_> = row
                                .labels
                                .0
                                .iter()
                                .map(|label| (&*label.name, &*label.value))
                                .collect();
                            let identity_label = format!("{identity:06}");
                            if grouped {
                                assert_eq!(labels, [(b"job".as_slice(), b"worker".as_slice())]);
                            } else {
                                let mut expected = Vec::new();
                                if filtered {
                                    expected.push((b"__name__".as_slice(), b"m".as_slice()));
                                }
                                expected.extend([
                                    (b"id".as_slice(), identity_label.as_bytes()),
                                    (b"job".as_slice(), b"worker".as_slice()),
                                ]);
                                assert_eq!(labels, expected);
                            }
                            assert_eq!(row.points.len(), 3);
                            let slope = if grouped {
                                (count.div_ceil(2) * 6 + count / 2 * 12) as f64
                            } else if filtered {
                                8.0
                            } else if identity.is_multiple_of(2) {
                                6.0
                            } else {
                                12.0
                            };
                            for (tick, point) in row.points.iter().enumerate() {
                                assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                                let value = if boolean {
                                    (identity % 2) as f64
                                } else {
                                    slope * (tick + 1) as f64
                                };
                                assert_eq!(float_bits(point), value.to_bits());
                            }
                        }
                        assert_eq!(report.observations.output_samples, 3 * rows as u64);
                        let fetched: usize = provider
                            .series
                            .iter()
                            .map(|row| row.source.counters.samples_returned.load(Ordering::Relaxed))
                            .sum();
                        assert_eq!(report.observations.samples_fetched, fetched as u64);
                        assert!(
                            provider.series.iter().all(|row| {
                                row.source.counters.peak.load(Ordering::Relaxed) == 1
                            })
                        );
                        assert_eq!(
                            report.observations.memory[MemoryKind::Workspace as usize].current,
                            0
                        );
                        println!(
                            "ordered-binary-growth expression={expression:?} delayed={delayed} rows={count} page={page} fetched={} work={}",
                            report.observations.samples_fetched, report.observations.work
                        );
                        if !delayed || matches!(expression, "m+n" | "m>n" | "m>bool n") {
                            growth.push((
                                report.observations.samples_fetched,
                                report.observations.work,
                            ));
                        }
                        provider.assert_closed();
                        drop((report, query));
                        engine.accounting.snapshot().assert_memory_released();
                        complete += 1;
                    }
                }
            }
        }
        assert_eq!(complete, 80);
        eprintln!("completed ordered binary controls: {complete}");
        assert!(
            growth
                .chunks_exact(4)
                .all(|rows| { rows[3].0 <= rows[1].0 * 6 && rows[3].1 <= rows[1].1 * 8 }),
            "ordered binary consumers must avoid repeated all-row reads: {growth:?}"
        );
    }

    #[test]
    fn root_delayed_join_preserves_actual_matrix_failure_phases() {
        let acquisitions = |provider: &FixtureProvider| {
            provider
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        for page in [1, 17, 1024] {
            let engine = Engine::default();
            let compiled = engine
                .compile(
                    b"m+n",
                    EngineOptions {
                        delayed_name_removal: true,
                        ..EngineOptions::default()
                    },
                    &Control::default(),
                )
                .unwrap();
            let mut landmarks: Vec<Vec<usize>> = Vec::new();
            let (mut selected, mut excluded) = (0, 0);
            for fault in ["none", "cold", "suffix", "warm", "next", "cancel"] {
                let control = Control::default();
                let mut provider = ordered_binary_provider(page, 4);
                // Ascending physical pairs leave a genuine unvisited suffix after the first output.
                for side in provider.series.chunks_mut(4) {
                    side.reverse();
                }
                let failed_at = match fault {
                    "cold" => Some((0, 0)),
                    "suffix" | "warm" | "cancel" => Some((0, 1)),
                    "next" => Some((1, 0)),
                    _ => None,
                };
                if fault != "none" && fault != "cancel" {
                    let (target, acquisition) = match fault {
                        "cold" => (excluded, landmarks[0][excluded] + 1),
                        "suffix" => (excluded, landmarks[1][excluded] + 1),
                        "warm" => (selected, landmarks[2][selected]),
                        "next" => (excluded, landmarks[3][excluded] + 1),
                        _ => unreachable!(),
                    };
                    provider.series[target].source.fail_acquisition = Some(acquisition);
                }
                let account = compiled.execution_accounting();
                {
                    let shape_header = compiled
                        .header(QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 3000,
                            step_ms: 1000,
                        })
                        .unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        shape_header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let initial = compiled.evaluation_options(header, 1000, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        initial,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        initial,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let mut rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let root = compiled.expression.root;
                    assert!(!rosters.binary(root).unwrap().has_pair_discovery());
                    compiled
                        .certify_pair_replay(
                            root,
                            shape_header,
                            header,
                            false,
                            &prepared,
                            &mut rosters,
                            &control,
                            &account,
                        )
                        .unwrap();
                    if fault == "none" {
                        landmarks.push(acquisitions(&provider));
                    } else {
                        assert_eq!(acquisitions(&provider), landmarks[0]);
                    }
                    'clocks: for clock in 0..2 {
                        let time = (clock + 1) * 1000;
                        let options = compiled.evaluation_options(header, time, &prepared);
                        let key = crate::vector_matching::ReplayKey::new(
                            options,
                            clock,
                            prepared.lookback_ns(options.lookback_ms),
                            bounds,
                        );
                        let plan = rosters.binary(root).unwrap();
                        assert!(!plan.has_completed_pair_replay(&key));
                        let mut machine = Machine::new(
                            &catalog,
                            &compiled.expression,
                            root,
                            options,
                            &control,
                            &account,
                            EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &compiled.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: None,
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            },
                        );
                        machine.set_step_index(clock);
                        for position in 0..4 {
                            let before = acquisitions(&provider);
                            if fault == "cancel" && (clock, position) == (0, 1) {
                                control.cancellation.cancel();
                            }
                            let result = machine.next();
                            if failed_at == Some((clock, position)) {
                                if fault == "cancel" {
                                    assert!(matches!(
                                        result,
                                        Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                    ));
                                    assert_eq!(acquisitions(&provider), before);
                                } else {
                                    assert!(
                                        matches!(&result, Err(EvaluationError::Storage(StorageError::Provider(bytes)))
                                        if &**bytes == b"injected page failure"),
                                        "{fault} {clock}:{position}"
                                    );
                                }
                                drop(result);
                                assert_eq!(plan.has_completed_pair_replay(&key), fault == "warm");
                                break 'clocks;
                            }
                            let sample = result.unwrap().unwrap();
                            let identity = sample
                                .labels
                                .0
                                .iter()
                                .find(|label| &*label.name == b"id")
                                .unwrap();
                            assert_eq!(&*identity.value, format!("{position:06}").as_bytes());
                            let descriptor = &rosters.descriptors(root)[position];
                            assert_eq!(sample.ordinal, descriptor.ordinal);
                            assert_eq!(sample.drop_name, descriptor.drop_name);
                            assert!(
                                crate::binary_labels::same(
                                    &sample.labels,
                                    &descriptor.labels,
                                    &control,
                                    &account
                                )
                                .unwrap()
                            );
                            let OwnedValue::Float(value) = sample.value else {
                                panic!("float join");
                            };
                            let expected = (if position.is_multiple_of(2) {
                                6.0
                            } else {
                                12.0
                            }) * (clock + 1) as f64;
                            assert_eq!(value.to_bits(), expected.to_bits());
                            assert_eq!(plan.has_completed_pair_replay(&key), position != 0);
                            if fault == "none" && clock == 0 && position < 2 {
                                landmarks.push(acquisitions(&provider));
                            }
                        }
                        assert!(machine.next().unwrap().is_none());
                        assert!(plan.has_completed_pair_replay(&key));
                        if fault == "none" && clock == 0 {
                            landmarks.push(acquisitions(&provider));
                        }
                    }
                }
                provider.assert_closed();
                account.snapshot().assert_memory_released();
                drop(account);
                if fault == "none" {
                    selected = provider
                        .series
                        .iter()
                        .position(|row| {
                            row.labels
                                .iter()
                                .any(|(name, value)| name == b"id" && value == b"000001")
                        })
                        .unwrap();
                    excluded = provider
                        .series
                        .iter()
                        .position(|row| {
                            row.labels
                                .iter()
                                .any(|(name, value)| name == b"id" && value == b"000002")
                        })
                        .unwrap();
                    assert_eq!(landmarks.len(), 4);
                    assert_eq!(landmarks[1][excluded], landmarks[0][excluded] + 1);
                    assert_eq!(landmarks[2][excluded], landmarks[1][excluded] + 1);
                    assert_eq!(landmarks[2][selected], landmarks[1][selected] + 2);
                    assert_eq!(landmarks[3][excluded], landmarks[2][excluded] + 1);
                    eprintln!("root Matrix acquisition phases page={page}: {landmarks:?}");
                }
            }
            drop(compiled);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn root_delayed_join_keeps_simultaneous_and_disjoint_name_aliases() {
        fn disjoint<const LEFT: bool>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(if (index != 1) == LEFT {
                    (index + 1) as f64
                } else {
                    f64::from_bits(crate::value::STALE_NAN_BITS)
                }),
            }
        }
        let expression = b"{__name__=~\"m|n\"} == bool on(__name__,id,job) {__name__=~\"m|n\"}";
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for separate in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut provider = ordered_binary_provider(page, 2);
                    if separate {
                        for (index, row) in provider.series.iter_mut().enumerate() {
                            row.source.sample = if index < 2 {
                                disjoint::<true>
                            } else {
                                disjoint::<false>
                            };
                        }
                    }
                    let compiled = engine
                        .compile(expression, options(delayed), &control)
                        .unwrap();
                    let report = compiled.collect_reported(
                        &provider,
                        QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 3000,
                            step_ms: 1000,
                        },
                        &control,
                    );
                    assert!(report.annotations.is_empty());
                    if separate {
                        let result = report.result.as_ref().unwrap();
                        assert_eq!(result.series.len(), 2);
                        for (index, row) in result.series.iter().enumerate() {
                            let labels: Vec<_> = row
                                .labels
                                .0
                                .iter()
                                .map(|label| (&*label.name, &*label.value))
                                .collect();
                            let identity = format!("{index:06}");
                            assert_eq!(
                                labels,
                                [(b"id".as_slice(), identity.as_bytes()), (b"job", b"worker")]
                            );
                            assert_eq!(row.points.len(), 3);
                            for (tick, point) in row.points.iter().enumerate() {
                                assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                                assert_eq!(float_bits(point), 1.0f64.to_bits());
                            }
                        }
                        assert_eq!(report.observations.output_samples, 6);
                    } else {
                        assert!(is_duplicate(report.result.as_ref().unwrap_err()));
                    }
                    assert_eq!(
                        report.observations.memory[MemoryKind::Workspace as usize].current,
                        0
                    );
                    provider.assert_closed();
                    drop((report, compiled));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn ordered_binary_preparation_preserves_local_and_fallback_boundaries() {
        let range = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for count in [0, 1, 4] {
                for (expression, supported) in [
                    ("sum by(job)(m+n)", true),
                    ("sum by(job)(m @ 2+n)", false),
                    ("sum by(job)(sum by(id)(m)+sum by(id)(n))", true),
                ] {
                    for (request, ranged) in [
                        (range, true),
                        (QueryRequest::Instant { time_ms: 2000 }, false),
                        (
                            QueryRequest::Range {
                                start_ms: 2000,
                                end_ms: 2000,
                                step_ms: 1000,
                            },
                            false,
                        ),
                    ] {
                        for delayed in [false, true] {
                            let engine = Engine::default();
                            let control = Control::default();
                            let compiled = engine
                                .compile(expression.as_bytes(), options(delayed), &control)
                                .unwrap();
                            let provider = ordered_binary_provider(page, count);
                            let (rows, _, plans) = float_map_join_preparation_with_discovery(
                                &compiled, &provider, request, &control,
                            );
                            assert_eq!(rows, usize::from(count != 0));
                            assert_eq!(
                                plans,
                                usize::from(supported && ranged && count > 1 && !delayed),
                                "{expression} {request:?} count{count} delayed{delayed}"
                            );
                            drop(compiled);
                            engine.accounting.snapshot().assert_memory_released();
                        }
                    }
                }
            }
            let engine = Engine::default();
            let control = Control::default();
            let compiled = engine
                .compile(b"sum by(job)(m+n)", options(false), &control)
                .unwrap();
            let mut provider = ordered_binary_provider(page, 4);
            provider.series[0].source.sample = |index| crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::FloatHistogram(
                    crate::histogram::FloatHistogram {
                        count: 1.0,
                        sum: 1.0,
                        zero_count: 1.0,
                        zero_threshold: 1.0,
                        ..crate::histogram::FloatHistogram::default()
                    },
                ),
            };
            let (_, _, plans) =
                float_map_join_preparation_with_discovery(&compiled, &provider, range, &control);
            assert_eq!(plans, 0, "mixed raw operands must retain fallback");
            drop(compiled);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn ordered_binary_inner_machines_preserve_cold_warm_and_next_clock_failures() {
        check_ordered_binary_inner_phases(
            b"sum by(job)(m+n)",
            |page| ordered_binary_provider(page, 4),
            1000,
            0,
            2,
            |identity, time| {
                (if identity.is_multiple_of(2) {
                    6.0
                } else {
                    12.0
                }) * (time / 1000) as f64
            },
        );
    }

    #[test]
    fn local_grouped_inner_machines_preserve_member_and_clock_failures() {
        for (left_window, right_window) in [(false, false), (true, false), (false, true)] {
            let left = if left_window {
                "rate(m_total[2s])"
            } else {
                "m_total"
            };
            let right = if right_window {
                "rate(n_total[2s])"
            } else {
                "n_total"
            };
            let expression =
                format!("sum by(job)(sum by(job,id)({left}) + on(job,id) sum by(job,id)({right}))");
            check_ordered_binary_inner_phases(
                expression.as_bytes(),
                |page| local_grouped_operand_provider(page, 4),
                2000,
                2,
                if left_window || right_window { 2 } else { 4 },
                |identity, time| {
                    let tick = (time / 1000) as f64;
                    let slope = if identity.is_multiple_of(2) {
                        6.0
                    } else {
                        24.0
                    };
                    slope
                        * if left_window {
                            2.0 * tick - 1.0
                        } else {
                            100.0 + tick * tick
                        }
                        + 4.0 * if right_window { 1.0 } else { 100.0 + tick }
                },
            );
        }
    }

    fn check_ordered_binary_inner_phases(
        expression: &[u8],
        make_provider: impl Fn(usize) -> FixtureProvider,
        start_ms: i64,
        expected_groups: usize,
        expected_warm_sources: usize,
        expected_value: impl Fn(usize, i64) -> f64,
    ) {
        let acquisitions = |provider: &FixtureProvider| {
            provider
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        for page in [1, 17, 1024] {
            let engine = Engine::default();
            let compiled = engine
                .compile(expression, options(false), &Control::default())
                .unwrap();
            let mut landmarks: Vec<Vec<usize>> = Vec::new();
            let (mut selected, mut nonmember) = (0, 0);
            let mut selected_identity = Vec::new();
            for fault in ["none", "cold", "warm", "next", "cancel"] {
                let control = Control::default();
                let mut provider = make_provider(page);
                let fault_phase = match fault {
                    "cold" => Some(0),
                    "warm" | "cancel" => Some(1),
                    "next" => Some(2),
                    _ => None,
                };
                if let Some(phase) = fault_phase
                    && fault != "cancel"
                {
                    let target = if fault == "warm" { selected } else { nonmember };
                    provider.series[target].source.fail_acquisition =
                        Some(landmarks[phase][target] + 1);
                }
                let account = compiled.execution_accounting();
                {
                    let header = compiled
                        .header(QueryRequest::Range {
                            start_ms,
                            end_ms: start_ms + 2000,
                            step_ms: 1000,
                        })
                        .unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let header = prepared.evaluator_header();
                    prepared.activate(header, &control, &account).unwrap();
                    let initial = compiled.evaluation_options(header, 1000, &prepared);
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        initial,
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let scope = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &scope,
                        &compiled.expression,
                        &prepared,
                        initial,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let joins: Vec<_> = (0..compiled.expression.arena.nodes.len())
                        .map(NodeId)
                        .filter(|&node| {
                            rosters
                                .binary(node)
                                .is_some_and(|plan| plan.has_pair_discovery())
                        })
                        .collect();
                    assert_eq!(joins.len(), 1);
                    let join = joins[0];
                    let plan = rosters.binary(join).unwrap();
                    let group_plans: Vec<_> = (0..compiled.expression.arena.nodes.len())
                        .filter_map(|index| rosters.group_replay(NodeId(index)))
                        .collect();
                    assert_eq!(group_plans.len(), expected_groups);
                    assert!(
                        group_plans.iter().all(|plan| !plan.has_completion()),
                        "preparation must clear contributor credit"
                    );
                    assert!(!plan.has_pair_candidate() && !plan.has_completed_pair_discovery());
                    let (rows, sources) = rosters.ordered(join).unwrap();
                    let ordinals = [0, 1].map(|position| {
                        let bindings = &sources[rows[position].sources.clone()];
                        assert_eq!(bindings.len(), 1);
                        bindings[0]
                    });
                    if fault == "none" {
                        selected_identity = rows[1]
                            .labels
                            .0
                            .iter()
                            .find(|label| &*label.name == b"id")
                            .unwrap()
                            .value
                            .to_vec();
                        landmarks.push(acquisitions(&provider));
                    } else {
                        assert_eq!(acquisitions(&provider), landmarks[0]);
                    }
                    for (phase, (time, step, ordinal)) in [
                        (start_ms, 0, ordinals[0]),
                        (start_ms, 0, ordinals[1]),
                        (start_ms + 1000, 1, ordinals[1]),
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        let options = compiled.evaluation_options(header, time, &prepared);
                        let before = acquisitions(&provider);
                        if fault == "cancel" && phase == 1 {
                            control.cancellation.cancel();
                        }
                        let mut machine = Machine::new(
                            &catalog,
                            &compiled.expression,
                            join,
                            options,
                            &control,
                            &account,
                            EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &compiled.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: None,
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            },
                        );
                        machine.restrict_one(ordinal);
                        machine.bypass_root_order();
                        machine.set_step_index(step);
                        let result = machine.next();
                        if fault_phase == Some(phase) {
                            if fault == "cancel" {
                                assert!(matches!(
                                    result,
                                    Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                ));
                                assert_eq!(acquisitions(&provider), before);
                            } else {
                                assert!(matches!(&result, Err(EvaluationError::Storage(
                                    StorageError::Provider(bytes))) if &**bytes == b"injected page failure"));
                            }
                            drop(result);
                            drop(machine);
                            if phase != 1 {
                                assert!(!plan.has_completed_pair_discovery());
                            }
                            if phase == 0 && !group_plans.is_empty() {
                                assert!(
                                    group_plans.iter().any(|plan| !plan.has_completion()),
                                    "failed cold child cannot grant complete group credit"
                                );
                            }
                            break;
                        }
                        let sample = result.unwrap().unwrap();
                        assert_eq!(sample.ordinal, ordinal);
                        let descriptor = &rows[usize::from(phase != 0)];
                        let labels = |labels: &crate::result::OwnedLabels| {
                            labels
                                .0
                                .iter()
                                .map(|label| (label.name.to_vec(), label.value.to_vec()))
                                .collect::<Vec<_>>()
                        };
                        assert_eq!(labels(&sample.labels), labels(&descriptor.labels));
                        let identity = std::str::from_utf8(
                            &descriptor
                                .labels
                                .0
                                .iter()
                                .find(|label| &*label.name == b"id")
                                .unwrap()
                                .value,
                        )
                        .unwrap()
                        .parse::<usize>()
                        .unwrap();
                        let OwnedValue::Float(value) = &sample.value else {
                            panic!("float join");
                        };
                        assert_eq!(value.to_bits(), expected_value(identity, time).to_bits());
                        drop(sample);
                        assert!(machine.next().unwrap().is_none());
                        drop(machine);
                        assert!(plan.has_completed_pair_discovery());
                        assert!(group_plans.iter().all(|plan| plan.has_completion()));
                        if fault == "none" {
                            landmarks.push(acquisitions(&provider));
                        }
                    }
                }
                provider.assert_closed();
                account.snapshot().assert_memory_released();
                drop(account);
                if fault == "none" {
                    let warm: Vec<_> = (0..provider.series.len())
                        .filter(|&index| landmarks[2][index] > landmarks[1][index])
                        .collect();
                    assert_eq!(
                        warm.len(),
                        expected_warm_sources,
                        "each uncached selected group member must be read freshly"
                    );
                    assert!(warm.iter().all(|&index| {
                        provider.series[index]
                            .labels
                            .iter()
                            .any(|(key, value)| key == b"id" && value == &selected_identity)
                    }));
                    selected = warm[0];
                    nonmember = (0..provider.series.len())
                        .find(|index| {
                            !warm.contains(index)
                                && landmarks[1][*index] > landmarks[0][*index]
                                && landmarks[3][*index] > landmarks[2][*index]
                        })
                        .unwrap();
                    assert!(landmarks[3][nonmember] > landmarks[2][nonmember]);
                }
            }
            for cancel in [false, true] {
                let provider = make_provider(page);
                let control = Control::default();
                let mut sink = RecordingSink {
                    fail_after: (!cancel).then_some(1),
                    cancel: cancel.then(|| control.cancellation.clone()),
                    ..RecordingSink::default()
                };
                let report = compiled.execute_reported(
                    &provider,
                    QueryRequest::Range {
                        start_ms,
                        end_ms: start_ms + 2000,
                        step_ms: 1000,
                    },
                    &control,
                    &mut sink,
                );
                if cancel {
                    assert!(matches!(
                        &report.result,
                        Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                            Interrupted::Cancelled
                        )))
                    ));
                } else {
                    assert!(matches!(&report.result, Err(ExecutionError::Sink(bytes))
                        if &**bytes == b"sink failure"));
                    report.assert_retained_callback_error_memory();
                }
                assert!(sink.begun && sink.aborted && !sink.committed);
                provider.assert_closed();
            }
            drop(compiled);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    fn float_map_join_provider(page: usize) -> FixtureProvider {
        let mut provider = FixtureProvider::new(3, page, 8);
        provider.filter_selectors = true;
        for (index, series) in provider.series.iter_mut().enumerate() {
            series.labels = vec![
                (
                    b"__name__".to_vec(),
                    if index < 4 { b"a" } else { b"b" }.to_vec(),
                ),
                (
                    b"instance".to_vec(),
                    [2, 0, 3, 1, 3, 1, 0, 2][index].to_string().into_bytes(),
                ),
            ];
            series.source.counters = Default::default();
        }
        provider
    }

    fn float_map_join_unit_provider(page: usize) -> FixtureProvider {
        let mut provider = float_map_join_provider(page);
        for series in &mut provider.series {
            series.source.sample = |index| crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(1.0),
            };
        }
        provider
    }

    fn float_map_join_preparation(
        compiled: &CompiledQuery,
        calibration: &FixtureProvider,
        request: QueryRequest,
        control: &Control,
    ) -> (usize, Vec<usize>) {
        let (descriptors, baseline, _) =
            float_map_join_preparation_with_discovery(compiled, calibration, request, control);
        (descriptors, baseline)
    }

    fn float_map_join_preparation_with_discovery(
        compiled: &CompiledQuery,
        calibration: &FixtureProvider,
        request: QueryRequest,
        control: &Control,
    ) -> (usize, Vec<usize>, usize) {
        let account = compiled.execution_accounting();
        let (descriptors, pair_plans) = {
            let header = compiled.header(request).unwrap();
            let prepared = Prepared::new(
                &compiled.expression,
                &compiled.preprocessing,
                header,
                compiled.options.no_step_subquery_interval_ms,
                control,
                &account,
            )
            .unwrap();
            let header = prepared.evaluator_header();
            prepared.activate(header, control, &account).unwrap();
            let options = compiled.evaluation_options(header, header.start_ms, &prepared);
            let bounds = crate::query_bounds::find(
                &compiled.expression,
                options,
                &prepared,
                control,
                &account,
            )
            .unwrap();
            let scope = calibration.open(bounds, control).unwrap();
            let catalog = Catalog::new(
                &scope,
                &compiled.expression,
                &prepared,
                options,
                compiled.options.no_step_subquery_interval_ms,
                control,
                &account,
            )
            .unwrap();
            let rosters = compiled
                .prepare_rosters(
                    &catalog,
                    &prepared,
                    bounds,
                    control,
                    &account,
                    &mut Annotations::default(),
                )
                .unwrap();
            let mut pair_plans = 0;
            for position in 0..compiled.expression.arena.nodes.len() {
                if let Some(plan) = rosters.binary(NodeId(position)) {
                    assert!(
                        !plan.has_pair_candidate(),
                        "preparation retained a candidate marker"
                    );
                    assert!(
                        !plan.has_completed_pair_discovery(),
                        "preparation retained pair progress"
                    );
                    pair_plans += usize::from(plan.has_pair_discovery());
                }
                if let Some(plan) = rosters.group_replay(NodeId(position)) {
                    assert!(
                        !plan.has_completion(),
                        "preparation retained contributor progress"
                    );
                }
                if let Some(plan) = rosters.sorting(NodeId(position))
                    && let Some(progress) = plan.emission_progress()
                {
                    assert_eq!(progress, 0, "preparation retained sort progress");
                }
            }
            (
                rosters.descriptors(compiled.expression.root).len(),
                pair_plans,
            )
        };
        calibration.assert_closed();
        account.snapshot().assert_memory_released();
        drop(account);
        let baseline = calibration
            .series
            .iter()
            .map(|series| series.source.counters.opened.load(Ordering::Relaxed))
            .collect();
        (descriptors, baseline, pair_plans)
    }

    #[test]
    fn wrapped_join_preparation_retains_moved_and_copied_input_eligibility() {
        let request = QueryRequest::Range {
            start_ms: 2000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for (expression, rows, admitted) in [
                ("abs(a_total / on(instance,member) b_total)", 4, true),
                (
                    "abs(sum by(instance)(a_total) / on(instance) sum by(instance)(b_total))",
                    2,
                    true,
                ),
                (
                    "abs((a_total*2) / on(instance,member) abs(b_total))",
                    4,
                    true,
                ),
                (
                    "(sum by(instance)(a_total) / on(instance) sum by(instance)(b_total))",
                    2,
                    true,
                ),
                (
                    "abs(sum by(instance)(rate(a_total[3s])) / on(instance) sum by(instance)(rate(b_total[3s])))",
                    2,
                    true,
                ),
                (
                    "abs(sum by(instance)(sum_over_time(a_total[3s])) / on(instance) sum by(instance)(sum_over_time(b_total[3s])))",
                    2,
                    true,
                ),
                (
                    "clamp_min((a_total / on(instance,member) b_total),scalar(vector(time())))",
                    4,
                    true,
                ),
                (
                    "abs(sum by(instance)(a_total @ 2) / on(instance) sum by(instance)(b_total))",
                    2,
                    false,
                ),
            ] {
                for delayed in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let compiled = engine
                        .compile(
                            expression.as_bytes(),
                            EngineOptions {
                                delayed_name_removal: delayed,
                                ..EngineOptions::default()
                            },
                            &control,
                        )
                        .unwrap();
                    let mut provider = float_map_join_unit_provider(page);
                    for (index, row) in provider.series.iter_mut().enumerate() {
                        row.labels[0].1 = if index < 4 { b"a_total" } else { b"b_total" }.to_vec();
                        row.labels[1].1 = ((index % 4) / 2).to_string().into_bytes();
                        row.labels
                            .push((b"member".to_vec(), (index % 2).to_string().into_bytes()));
                    }
                    let (descriptors, _, pair_plans) = float_map_join_preparation_with_discovery(
                        &compiled, &provider, request, &control,
                    );
                    assert_eq!(descriptors, rows, "{expression} delayed{delayed}");
                    assert_eq!(
                        pair_plans,
                        usize::from(admitted && !delayed),
                        "{expression} delayed{delayed}"
                    );
                    if expression.starts_with("clamp_min(") {
                        let report = compiled.collect_reported(&provider, request, &control);
                        assert!(report.annotations.is_empty());
                        let result = report.result.as_ref().unwrap();
                        assert_eq!(result.series.len(), 4);
                        for row in &*result.series {
                            assert_eq!(row.points.len(), 2);
                            for (index, point) in row.points.iter().enumerate() {
                                assert_eq!(point.time_ms, (index as i64 + 2) * 1000);
                                assert_eq!(float_bits(point), (index as f64 + 2.0).to_bits());
                            }
                        }
                        provider.assert_closed();
                    }
                    drop(compiled);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    fn window_join_failures(function: &str, normalize_fold: bool) {
        let request = QueryRequest::Range {
            start_ms: 2000,
            end_ms: 3000,
            step_ms: 1000,
        };
        let acquisitions = |input: &FixtureProvider| {
            input
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        let provider = |page| {
            let mut input = float_map_join_unit_provider(page);
            for (index, row) in input.series.iter_mut().enumerate() {
                row.labels[0].1 = if index < 4 { b"a_total" } else { b"b_total" }.to_vec();
            }
            input
        };
        for page in [1, 17, 1024] {
            for (template, selected) in [
                ("clamp_min(rate(a_total[3s]),0) / on(instance) b_total", 5),
                (
                    "abs(clamp_min(rate(a_total[3s]),-time())) / on(instance) b_total",
                    5,
                ),
                ("a_total / on(instance) abs(rate(b_total[3s]))", 3),
                ("a_total / on(instance) (100*+rate(b_total[3s]))", 3),
            ] {
                let expression = if normalize_fold {
                    template
                        .replace("rate(a_total[3s])", &format!("({function}(a_total[3s])*0)"))
                        .replace("rate(b_total[3s])", &format!("({function}(b_total[3s])*0)"))
                } else {
                    template.replace("rate(", &format!("{function}("))
                };
                let engine = Engine::default();
                let control = Control::default();
                let mut options = EngineOptions::default();
                options.parser.experimental_functions = normalize_fold;
                let compiled = engine
                    .compile(expression.as_bytes(), options, &control)
                    .unwrap();
                let calibration = provider(page);
                let (descriptors, prepared) =
                    float_map_join_preparation(&compiled, &calibration, request, &control);
                assert_eq!(descriptors, 4);
                let mut landmarks = Vec::new();
                for outputs in [1, 2] {
                    let input = provider(page);
                    let mut sink = RecordingSink {
                        fail_after: Some(outputs),
                        ..RecordingSink::default()
                    };
                    let report = compiled.execute_reported(&input, request, &control, &mut sink);
                    assert!(matches!(&report.result, Err(ExecutionError::Sink(bytes))
                        if &**bytes == b"sink failure"));
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(sink.chunks, outputs);
                    assert_eq!(report.observations.output_samples, outputs as u64 - 1);
                    landmarks.push(acquisitions(&input));
                    report.assert_retained_callback_error_memory();
                    input.assert_closed();
                }
                assert!(
                    landmarks[1][selected] > landmarks[0][selected],
                    "the next output must actually read the selected raw operand"
                );
                for (phase, target, acquisition, outputs) in [
                    ("cold-suffix", 7, prepared[7] + 1, 0),
                    ("warm-selected", selected, landmarks[0][selected] + 1, 1),
                ] {
                    let mut input = provider(page);
                    input.series[target].source.fail_acquisition = Some(acquisition);
                    let mut sink = RecordingSink {
                        fail_after: Some(outputs + 1),
                        ..RecordingSink::default()
                    };
                    let report = compiled.execute_reported(&input, request, &control, &mut sink);
                    assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                        EvaluationError::Storage(StorageError::Provider(bytes))))
                        if &**bytes == b"injected page failure"));
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(sink.chunks, outputs, "{expression} {phase} page{page}");
                    assert_eq!(report.observations.output_samples, outputs as u64);
                    assert_eq!(acquisitions(&input)[target], acquisition);
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    input.assert_closed();
                    println!(
                        "{{\"mapped_rate_join_phase\":\"{phase}\",\"expression\":{expression:?},\"page_size\":{page},\"target\":{target},\"preparation_acquisitions\":{},\"acquisitions\":{acquisition},\"output_samples\":{outputs}}}",
                        prepared[target]
                    );
                }
                let input = provider(page);
                let report = compiled.collect_reported(&input, request, &control);
                let result = report.result.as_ref().unwrap();
                assert_eq!(result.series.len(), 4);
                for (index, row) in result.series.iter().enumerate() {
                    assert_eq!(row.labels.0.len(), 1);
                    assert_eq!(&*row.labels.0[0].name, b"instance");
                    assert_eq!(&*row.labels.0[0].value, index.to_string().as_bytes());
                    assert_eq!(row.points.len(), 2);
                    for (tick, point) in row.points.iter().enumerate() {
                        assert_eq!(point.time_ms, (tick as i64 + 2) * 1000);
                        let OwnedValue::Float(value) = point.value else {
                            panic!("mapped rate join must return a float");
                        };
                        let expected: f64 = if selected == 5 { 0.0 } else { f64::INFINITY };
                        assert_eq!(value.to_bits(), expected.to_bits());
                    }
                }
                assert_eq!(report.observations.output_samples, 8);
                assert_eq!(
                    report
                        .observations
                        .statistics
                        .samples
                        .total_queryable_samples,
                    28
                );
                assert!(report.annotations.is_empty());
                input.assert_closed();
                drop((report, compiled));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn mapped_rate_join_preserves_cold_suffix_and_warm_selected_failures() {
        window_join_failures("rate", false);
    }

    #[test]
    fn range_rate_joins_preserve_cold_suffix_and_warm_selected_failures() {
        for function in ["increase", "delta", "irate", "idelta"] {
            window_join_failures(function, false);
        }
    }

    #[test]
    fn per_series_fold_joins_preserve_cold_suffix_and_warm_selected_failures() {
        for function in crate::frontend::functions::FUNCTIONS {
            if function.name != "absent_over_time"
                && matches!(
                    RangeFunction::parse(function.name),
                    Some(RangeFunction::Fold(_))
                )
            {
                window_join_failures(function.name, true);
            }
        }
    }

    #[test]
    fn grouped_aggregate_joins_keep_cold_nonmember_and_warm_selected_errors() {
        let request = QueryRequest::Range {
            start_ms: 2000,
            end_ms: 3000,
            step_ms: 1000,
        };
        let provider = |page| {
            let mut input = float_map_join_unit_provider(page);
            for (index, row) in input.series.iter_mut().enumerate() {
                row.labels[0].1 = if index < 4 { b"a_total" } else { b"b_total" }.to_vec();
                row.labels[1].1 = ((index % 4) / 2).to_string().into_bytes();
                row.labels
                    .push((b"member".to_vec(), (index % 2).to_string().into_bytes()));
            }
            input
        };
        let acquisitions = |input: &FixtureProvider| {
            input
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect::<Vec<_>>()
        };
        for operator in [
            "sum", "avg", "count", "min", "max", "group", "stdvar", "stddev",
        ] {
            for (left_template, right_template, selected, window_side) in [
                (
                    "{op} by(instance)({metric})",
                    "{op} by(instance)({metric})",
                    7,
                    0,
                ),
                (
                    "{op} without(member)(rate({metric}[3s]))",
                    "{op} by(instance)({metric})",
                    7,
                    1,
                ),
                (
                    "{op} by(instance)({metric})",
                    "{op} without(member)(rate({metric}[3s]))",
                    3,
                    2,
                ),
                (
                    "clamp_min({op} by(instance)(abs({metric})),0)",
                    "clamp_min({op} by(instance)(abs({metric})),0)",
                    7,
                    0,
                ),
                (
                    "sum by(instance)({op} by(instance,member)({metric}))",
                    "sum by(instance)({op} by(instance,member)({metric}))",
                    7,
                    0,
                ),
            ] {
                let left = left_template
                    .replace("{op}", operator)
                    .replace("{metric}", "a_total");
                let right = right_template
                    .replace("{op}", operator)
                    .replace("{metric}", "b_total");
                let expression = format!("({left}+1) / on(instance) ({right}+1)");
                for page in [1, 17, 1024] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let compiled = engine
                        .compile(expression.as_bytes(), EngineOptions::default(), &control)
                        .unwrap();
                    let calibration = provider(page);
                    let (descriptors, prepared) =
                        float_map_join_preparation(&compiled, &calibration, request, &control);
                    assert_eq!(descriptors, 2);
                    let mut landmarks = Vec::new();
                    for outputs in [1, 2] {
                        let input = provider(page);
                        let mut sink = RecordingSink {
                            fail_after: Some(outputs),
                            ..RecordingSink::default()
                        };
                        let report =
                            compiled.execute_reported(&input, request, &control, &mut sink);
                        assert!(
                            matches!(&report.result, Err(ExecutionError::Sink(bytes)) if &**bytes == b"sink failure")
                        );
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(sink.chunks, outputs);
                        assert_eq!(report.observations.output_samples, outputs as u64 - 1);
                        landmarks.push(acquisitions(&input));
                        report.assert_retained_callback_error_memory();
                        input.assert_closed();
                    }
                    assert!(
                        landmarks[1][selected] > landmarks[0][selected],
                        "second group must freshly read its last member: {expression}"
                    );
                    for (phase, acquisition, outputs) in [
                        ("cold-nonmember", prepared[selected] + 1, 0),
                        ("warm-selected", landmarks[0][selected] + 1, 1),
                    ] {
                        let mut input = provider(page);
                        input.series[selected].source.fail_acquisition = Some(acquisition);
                        let mut sink = RecordingSink {
                            fail_after: Some(outputs + 1),
                            ..RecordingSink::default()
                        };
                        let report =
                            compiled.execute_reported(&input, request, &control, &mut sink);
                        assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                            EvaluationError::Storage(StorageError::Provider(bytes)))) if &**bytes == b"injected page failure"));
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(sink.chunks, outputs, "{phase} {expression} page{page}");
                        assert_eq!(report.observations.output_samples, outputs as u64);
                        assert_eq!(acquisitions(&input)[selected], acquisition);
                        assert!(report.annotations.is_empty());
                        report.assert_retained_callback_error_memory();
                        input.assert_closed();
                        println!(
                            "{{\"group_contributor_phase\":\"{phase}\",\"query\":{expression:?},\"page\":{page},\"target\":{selected},\"acquisition\":{acquisition},\"output_samples\":{outputs}}}"
                        );
                    }
                    {
                        let input = provider(page);
                        let cancelled = Control::default();
                        let mut sink = RecordingSink {
                            cancel: Some(cancelled.cancellation.clone()),
                            ..RecordingSink::default()
                        };
                        let report =
                            compiled.execute_reported(&input, request, &cancelled, &mut sink);
                        assert!(matches!(
                            report.result,
                            Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                                Interrupted::Cancelled
                            )))
                        ));
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(sink.chunks, 2);
                        input.assert_closed();
                    }
                    let input = provider(page);
                    let report = compiled.collect_reported(&input, request, &control);
                    let result = report.result.as_ref().unwrap();
                    let raw: f64 = match operator {
                        "sum" | "count" => 2.0,
                        "stdvar" | "stddev" => 0.0,
                        _ => 1.0,
                    };
                    let window: f64 = match operator {
                        "count" => 2.0,
                        "group" => 1.0,
                        _ => 0.0,
                    };
                    let expected: f64 = match window_side {
                        1 => (window + 1.0) / (raw + 1.0),
                        2 => (raw + 1.0) / (window + 1.0),
                        _ => 1.0,
                    };
                    assert!(report.annotations.is_empty());
                    assert_eq!(result.series.len(), 2);
                    assert_eq!(report.observations.output_samples, 4);
                    for (ordinal, series) in result.series.iter().enumerate() {
                        assert_eq!(series.labels.0.len(), 1);
                        assert_eq!(&*series.labels.0[0].name, b"instance");
                        assert_eq!(&*series.labels.0[0].value, ordinal.to_string().as_bytes());
                        assert_eq!(series.points.len(), 2);
                        for (tick, point) in series.points.iter().enumerate() {
                            assert_eq!(point.time_ms, (tick as i64 + 2) * 1000);
                            assert!(
                                matches!(point.value, OwnedValue::Float(value) if value.to_bits() == expected.to_bits())
                            );
                        }
                    }
                    input.assert_closed();
                    drop((report, compiled));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn completed_float_map_join_preserves_cold_pair_and_warm_selected_failures() {
        let request = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for (template, native, direct) in [
                ("abs({x})", false, true),
                ("ceil({x})", false, true),
                ("round({x})", false, true),
                ("year({x})", false, true),
                ("round({x}, .5)", false, true),
                ("clamp_min({x}, 0)", false, true),
                ("clamp_max({x}, 4)", false, true),
                ("clamp({x}, 0, 4)", false, true),
                ("round(abs({x}), .5)", false, false),
                ("abs(({x}*1))", false, false),
                ("abs(timestamp(+{x}))", false, false),
                (
                    "abs(label_join({x}, \"instance\", \"\", \"source\"))",
                    false,
                    false,
                ),
                ("abs(histogram_count({x}))", true, false),
                ("round(histogram_sum({x}), .5)", true, false),
                ("clamp(histogram_avg({x}), 0, Inf)", true, false),
                ("({x}*100)", false, false),
                ("(100*{x})", false, false),
                ("(-{x})", false, false),
                ("(+{x})", false, false),
                (
                    "label_join({x}, \"instance\", \"\", \"source\")",
                    false,
                    false,
                ),
                ("timestamp(+{x})", false, false),
                ("histogram_count({x})", true, false),
                ("histogram_sum({x})", true, false),
                ("histogram_avg({x})", true, false),
            ] {
                for route in ["left", "right", "both"] {
                    // A rewritten left identity keeps the existing right-side failure landmark distinct.
                    if template.contains("label_join") && route != "left" {
                        continue;
                    }
                    let bare_label = template.starts_with("label_join(");
                    let left_wrapped = route != "right";
                    let right_wrapped = route != "left";
                    let left = if left_wrapped {
                        template.replace("{x}", "a")
                    } else {
                        "a".into()
                    };
                    let right = if right_wrapped {
                        template.replace("{x}", "b")
                    } else {
                        "b".into()
                    };
                    let provider = || {
                        let mut input = float_map_join_provider(page);
                        for (index, row) in input.series.iter_mut().enumerate() {
                            let source = [3, 1, 0, 2, 0, 2, 1, 3][index].to_string().into_bytes();
                            row.labels.push((b"source".to_vec(), source));
                            if native
                                && ((index < 4 && left_wrapped) || (index >= 4 && right_wrapped))
                            {
                                row.source.sample = |index| crate::value::Sample {
                                    time_ms: (index as i64 + 1) * 1000,
                                    start_time_ms: 0,
                                    value: crate::value::SampleValue::FloatHistogram(
                                        crate::histogram::FloatHistogram {
                                            count: 1.0,
                                            sum: 1.0,
                                            zero_count: 1.0,
                                            zero_threshold: 1.0,
                                            ..crate::histogram::FloatHistogram::default()
                                        },
                                    ),
                                };
                            }
                        }
                        input
                    };
                    let expression = format!("{left} / on(instance) {right}");
                    let engine = Engine::default();
                    let control = Control::default();
                    let compiled = engine
                        .compile(expression.as_bytes(), EngineOptions::default(), &control)
                        .unwrap();
                    let calibration = provider();
                    let (descriptors, baseline) =
                        float_map_join_preparation(&compiled, &calibration, request, &control);
                    assert_eq!(descriptors, 4);
                    if direct {
                        for (index, &count) in baseline.iter().enumerate() {
                            assert_eq!(
                                count,
                                if (index < 4 && left_wrapped) || (index >= 4 && right_wrapped) {
                                    8
                                } else {
                                    7
                                }
                            );
                        }
                    }
                    for phase in ["none", "discovery", "early-pair", "pair", "selected"] {
                        if phase == "early-pair" && !bare_label {
                            continue;
                        }
                        let mut input = provider();
                        // Bare projection keeps child order; right7 follows the first requested output.
                        let target = if phase == "discovery" || bare_label && phase == "pair" {
                            7
                        } else {
                            5
                        };
                        let acquisition = baseline[target]
                            + match phase {
                                "discovery" => 1,
                                "pair" | "early-pair" => 2,
                                _ => 3,
                            };
                        if phase != "none" {
                            input.series[target].source.fail_acquisition = Some(acquisition);
                        }
                        let mut sink = RecordingSink::default();
                        let report =
                            compiled.execute_reported(&input, request, &control, &mut sink);
                        if phase == "none" {
                            report.result.as_ref().unwrap();
                            assert!(sink.committed && !sink.aborted);
                            assert_eq!(sink.chunks, 12);
                            assert_eq!(report.observations.output_samples, 12);
                            assert_eq!(
                                report
                                    .observations
                                    .statistics
                                    .samples
                                    .total_queryable_samples,
                                // Native histogram samples use the pinned eleven-unit weight.
                                12 * (if native && left_wrapped { 11 } else { 1 }
                                    + if native && right_wrapped { 11 } else { 1 })
                            );
                        } else {
                            assert!(
                                matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Storage(
                            StorageError::Provider(bytes)))) if &**bytes == b"injected page failure")
                            );
                            assert!(sink.begun && sink.aborted && !sink.committed);
                            let points = usize::from(phase != "discovery" && phase != "early-pair");
                            assert_eq!(sink.chunks, points, "{expression} {phase} page{page}");
                            assert_eq!(report.observations.output_samples, points as u64);
                            assert_eq!(
                                input.series[target]
                                    .source
                                    .counters
                                    .opened
                                    .load(Ordering::Relaxed),
                                acquisition
                            );
                            if phase == "selected" {
                                let unselected: &[usize] = if bare_label {
                                    &[0, 2, 3, 4, 6, 7]
                                } else {
                                    &[0, 2, 4, 7]
                                };
                                for &index in unselected {
                                    assert_eq!(
                                        input.series[index]
                                            .source
                                            .counters
                                            .opened
                                            .load(Ordering::Relaxed),
                                        baseline[index] + 2,
                                        "unselected physical row{index} must not be reacquired after completed first delivery"
                                    );
                                }
                            }
                            report.assert_retained_callback_error_memory();
                        }
                        assert!(report.annotations.is_empty());
                        println!(
                            "{{\"float_map_join_phase\":\"{phase}\",\"expression\":{expression:?},\"page_size\":{page},\"target\":{target},\"preparation_acquisitions\":{},\"acquisitions\":{},\"output_samples\":{}}}",
                            baseline[target],
                            input.series[target]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            report.observations.output_samples
                        );
                        input.assert_closed();
                        drop(report);
                    }
                    drop(compiled);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn completed_float_map_join_preserves_empty_populated_empty_scopes_and_nan_presence() {
        let request = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for (expression, expected) in [
                    (
                        "round(clamp(a, 0, .5-(time()-2)^2), .5) / on(instance) b",
                        [(2000, 0.5)].as_slice(),
                    ),
                    (
                        "round(clamp(a, NaN, .5-(time()-2)^2), .5) > bool on(instance) b",
                        [(1000, 0.0), (2000, 0.0), (3000, 0.0)].as_slice(),
                    ),
                    (
                        "clamp(a, 0, .5-(time()-2)^2) / on(instance) b",
                        [(2000, 0.5)].as_slice(),
                    ),
                    (
                        "clamp(a, NaN, .5-(time()-2)^2) > bool on(instance) b",
                        [(1000, 0.0), (2000, 0.0), (3000, 0.0)].as_slice(),
                    ),
                    (
                        "clamp(a, 0, NaN) > bool on(instance) b",
                        [(1000, 0.0), (2000, 0.0), (3000, 0.0)].as_slice(),
                    ),
                    (
                        "(a > .5+(time()-2)^2) / on(instance) b",
                        [(2000, 1.0)].as_slice(),
                    ),
                    (
                        "((.5+(time()-2)^2) < a) / on(instance) b",
                        [(2000, 1.0)].as_slice(),
                    ),
                    (
                        "(a > bool .5+(time()-2)^2) / on(instance) b",
                        [(1000, 0.0), (2000, 1.0), (3000, 0.0)].as_slice(),
                    ),
                    (
                        "((.5+(time()-2)^2) < bool a) / on(instance) b",
                        [(1000, 0.0), (2000, 1.0), (3000, 0.0)].as_slice(),
                    ),
                ] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let input = float_map_join_unit_provider(page);
                    let compiled = engine
                        .compile(expression.as_bytes(), options(delayed), &control)
                        .unwrap();
                    let report = compiled.collect_reported(&input, request, &control);
                    let output = report.result.as_ref().unwrap();
                    assert_eq!(output.series.len(), 4, "{expression} page{page}");
                    for (id, row) in output.series.iter().enumerate() {
                        assert_eq!(row.labels.0.len(), 1);
                        assert_eq!(&*row.labels.0[0].name, b"instance");
                        assert_eq!(&*row.labels.0[0].value, id.to_string().as_bytes());
                        assert_eq!(row.points.len(), expected.len());
                        for (point, &(time_ms, value)) in row.points.iter().zip(expected) {
                            assert_eq!(point.time_ms, time_ms);
                            let OwnedValue::Float(actual) = point.value else {
                                panic!("{expression} must emit a float");
                            };
                            assert_eq!(actual.to_bits(), f64::to_bits(value), "{expression}");
                        }
                    }
                    assert_eq!(
                        report.observations.output_samples,
                        4 * expected.len() as u64
                    );
                    assert_eq!(
                        report
                            .observations
                            .statistics
                            .samples
                            .total_queryable_samples,
                        24
                    );
                    assert!(report.annotations.is_empty());
                    input.assert_closed();
                    drop((report, compiled));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn completed_float_map_join_preserves_faults_across_empty_scope_replacement() {
        let request = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            for expression in [
                "clamp(a, 0, .5-(time()-2)^2) / on(instance) b",
                "round(clamp(a, 0, .5-(time()-2)^2), .5) / on(instance) b",
                "(a > .5+(time()-2)^2) / on(instance) b",
                "((.5+(time()-2)^2) < a) / on(instance) b",
            ] {
                let engine = Engine::default();
                let control = Control::default();
                let compiled = engine
                    .compile(expression.as_bytes(), EngineOptions::default(), &control)
                    .unwrap();
                let calibration = float_map_join_unit_provider(page);
                let (descriptors, baseline) =
                    float_map_join_preparation(&compiled, &calibration, request, &control);
                assert_eq!(
                    descriptors, 4,
                    "an empty first tick must still reach final evaluation"
                );
                for fail_after in [Some(1), Some(4), None] {
                    let input = float_map_join_unit_provider(page);
                    let mut sink = RecordingSink {
                        fail_after,
                        ..RecordingSink::default()
                    };
                    let report = compiled.execute_reported(&input, request, &control, &mut sink);
                    if let Some(outputs) = fail_after {
                        assert!(matches!(&report.result, Err(ExecutionError::Sink(bytes))
                        if &**bytes == b"sink failure"));
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(sink.chunks, outputs);
                        assert_eq!(report.observations.output_samples, outputs as u64 - 1);
                    } else {
                        report.result.as_ref().unwrap();
                        assert!(sink.committed && !sink.aborted);
                        assert_eq!(sink.chunks, 4);
                        assert_eq!(report.observations.output_samples, 4);
                    }
                    for (index, &preparation) in baseline.iter().enumerate() {
                        // Cold delivery finishes every pair before later rows may reuse its membership.
                        let final_acquisitions = match fail_after {
                            Some(1) => 2 + usize::from([1, 6].contains(&index)),
                            Some(4) => 3 + usize::from(![1, 6].contains(&index)),
                            None => 4 + usize::from(![1, 6].contains(&index)),
                            _ => unreachable!(),
                        };
                        assert_eq!(
                            input.series[index]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            preparation + final_acquisitions,
                            "page{page} output{fail_after:?} physical{index}"
                        );
                    }
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    input.assert_closed();
                    drop(report);
                }
                for (phase, target, final_acquisition, outputs) in [
                    ("first-empty-left", 2, 1, 0),
                    ("first-empty-right", 7, 1, 0),
                    ("next-scope", 7, 2, 0),
                    ("cold-pair-suffix", 5, 3, 1),
                    ("warm-selected", 5, 4, 1),
                    ("last-empty", 7, 5, 4),
                ] {
                    let mut input = float_map_join_unit_provider(page);
                    let acquisition = baseline[target] + final_acquisition;
                    input.series[target].source.fail_acquisition = Some(acquisition);
                    let mut sink = RecordingSink::default();
                    let report = compiled.execute_reported(&input, request, &control, &mut sink);
                    assert!(matches!(&report.result, Err(ExecutionError::Evaluation(
                    EvaluationError::Storage(StorageError::Provider(bytes))))
                    if &**bytes == b"injected page failure"));
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(sink.chunks, outputs, "{phase} page{page}");
                    assert_eq!(report.observations.output_samples, outputs as u64);
                    assert_eq!(
                        input.series[target]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        acquisition
                    );
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    println!(
                        "{{\"float_map_join_empty_scope_phase\":\"{phase}\",\"page_size\":{page},\"target\":{target},\"preparation_acquisitions\":{},\"acquisitions\":{acquisition},\"output_samples\":{outputs}}}",
                        baseline[target]
                    );
                    input.assert_closed();
                    drop(report);
                }
                drop(compiled);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn nested_sort_prefix_preserves_preparation_reset_suffix_and_selected_failures() {
        fn provider(page: usize) -> FixtureProvider {
            fn sample(value: f64) -> crate::value::Sample {
                crate::value::Sample {
                    time_ms: 1000,
                    start_time_ms: 0,
                    value: crate::value::SampleValue::Float(value),
                }
            }
            let values: [fn(usize) -> crate::value::Sample; 4] = [
                |_| sample(2.0),
                |_| sample(4.0),
                |_| sample(1.0),
                |_| sample(3.0),
            ];
            let mut input = FixtureProvider::new(1, page, 4);
            for (series, generator) in input.series.iter_mut().zip(values) {
                series.source.sample = generator;
                series.source.counters = Default::default();
            }
            input
        }
        let request = QueryRequest::Range {
            start_ms: 1000,
            end_ms: 1001,
            step_ms: 1000,
        };
        for page in [1, 17, 1024] {
            let engine = Engine::default();
            let control = Control::default();
            let bare = engine
                .compile(b"sort(counter_total)", EngineOptions::default(), &control)
                .unwrap();
            let compiled = engine
                .compile(
                    b"abs(sort(counter_total))",
                    EngineOptions::default(),
                    &control,
                )
                .unwrap();
            let (bare_rows, base) =
                float_map_join_preparation(&bare, &provider(page), request, &control);
            let (rows, prepared) =
                float_map_join_preparation(&compiled, &provider(page), request, &control);
            assert_eq!((bare_rows, rows), (4, 4));
            assert_eq!(
                prepared
                    .iter()
                    .zip(&base)
                    .map(|(p, b)| p - b)
                    .collect::<Vec<_>>(),
                [1, 1, 2, 2]
            );
            for (phase, target, acquisition, outputs) in [
                ("none", 0, 0, 4),
                ("preparation-prefix", 2, base[2] + 1, 0),
                ("same-key-cold-prefix", 2, prepared[2] + 1, 0),
                ("unverified-suffix", 3, prepared[3] + 1, 1),
                ("fresh-selected", 2, prepared[2] + 2, 2),
            ] {
                let mut input = provider(page);
                if phase != "none" {
                    input.series[target].source.fail_acquisition = Some(acquisition);
                }
                let account = compiled.execution_accounting();
                let mut sink = RecordingSink::default();
                let mut report =
                    compiled.execute_reported_in(&input, request, &control, &mut sink, &account);
                if phase == "none" {
                    report.result.as_ref().unwrap();
                    assert!(sink.begun && sink.committed && !sink.aborted);
                    assert_eq!(sink.chunks, 5);
                    assert_eq!(report.observations.output_samples, 4);
                    assert_eq!(
                        report
                            .observations
                            .statistics
                            .samples
                            .total_queryable_samples,
                        4
                    );
                    let acquired: Vec<_> = input
                        .series
                        .iter()
                        .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                        .collect();
                    assert_eq!(
                        acquired
                            .iter()
                            .zip(&prepared)
                            .map(|(a, p)| a - p)
                            .collect::<Vec<_>>(),
                        [1, 1, 2, 2]
                    );
                    let output = compiled.collect_reported(&provider(page), request, &control);
                    let result = output.result.as_ref().unwrap();
                    assert_eq!(result.series.len(), 4);
                    for ((row, value), id) in
                        result.series.iter().zip([2.0_f64, 4.0, 1.0, 3.0]).zip(0..4)
                    {
                        assert_eq!(row.labels.0.len(), 2);
                        assert_eq!(&*row.labels.0[0].name, b"instance");
                        assert_eq!(&*row.labels.0[0].value, id.to_string().as_bytes());
                        assert_eq!(&*row.labels.0[1].name, b"job");
                        assert_eq!(&*row.labels.0[1].value, b"worker");
                        assert_eq!(row.points.len(), 1);
                        assert_eq!(row.points[0].time_ms, 1000);
                        assert_eq!(float_bits(&row.points[0]), value.to_bits());
                    }
                } else {
                    assert!(
                        matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Storage(StorageError::Provider(bytes)))) if &**bytes == b"injected page failure")
                    );
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(sink.chunks, outputs, "{phase},page={page}");
                    assert_eq!(report.observations.output_samples, outputs as u64);
                    assert_eq!(
                        input.series[target]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        acquisition
                    );
                    if phase == "same-key-cold-prefix" {
                        for (position, series) in input.series.iter().enumerate() {
                            if position != target {
                                assert_eq!(
                                    series.source.counters.opened.load(Ordering::Relaxed),
                                    prepared[position]
                                );
                            }
                        }
                    }
                    drop(std::mem::take(&mut report.annotations));
                    report.observations = account.snapshot();
                    report.assert_retained_callback_error_memory();
                }
                println!(
                    "{{\"nested_sort_failure\":\"{phase}\",\"page_size\":{page},\"chunks\":{},\"prepared\":{prepared:?},\"acquisitions\":{}}}",
                    sink.chunks,
                    input.series[target]
                        .source
                        .counters
                        .opened
                        .load(Ordering::Relaxed)
                );
                input.assert_closed();
                drop(report);
                account.snapshot().assert_memory_released();
            }
            drop((bare, compiled));
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn completed_sort_emission_preserves_first_suffix_and_warm_selected_failures() {
        for page in [1, 17, 1024] {
            for descending in [false, true] {
                for phase in ["none", "suffix", "selected"] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut provider = FixtureProvider::new(3, page, 43);
                    for (index, series) in provider.series.iter_mut().enumerate() {
                        series.labels[1].1 = format!("{index:02}").into_bytes();
                        series.labels.push((
                            b"order".to_vec(),
                            format!("{:02}", if descending { 42 - index } else { index })
                                .into_bytes(),
                        ));
                        series.source.counters = Default::default();
                    }
                    let acquisition = if phase == "suffix" { 9 } else { 10 };
                    if phase != "none" {
                        provider.series[42].source.fail_acquisition = Some(acquisition);
                    }
                    let expression = if descending {
                        b"sort_by_label_desc(counter_total,\"order\")".as_slice()
                    } else {
                        b"sort_by_label(counter_total,\"order\")".as_slice()
                    };
                    let mut options = EngineOptions::default();
                    options.parser.experimental_functions = true;
                    let query = engine.compile(expression, options, &control).unwrap();
                    let mut sink = RecordingSink::default();
                    let account = query.execution_accounting();
                    let mut report = query.execute_reported_in(
                        &provider,
                        QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 3000,
                            step_ms: 1000,
                        },
                        &control,
                        &mut sink,
                        &account,
                    );
                    if phase == "none" {
                        report.result.as_ref().unwrap();
                        assert!(sink.committed && !sink.aborted);
                        assert_eq!(sink.chunks, 130);
                        assert_eq!(report.annotations.len(), 1);
                        assert_eq!(report.observations.output_samples, 129);
                        assert_eq!(
                            report
                                .observations
                                .statistics
                                .samples
                                .total_queryable_samples,
                            129
                        );
                    } else {
                        assert!(matches!(
                            &report.result,
                            Err(ExecutionError::Evaluation(EvaluationError::Storage(
                                StorageError::Provider(bytes)
                            ))) if &**bytes == b"injected page failure"
                        ));
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        assert_eq!(
                            provider.series[42]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            acquisition
                        );
                        if phase == "suffix" {
                            assert_eq!(sink.chunks, 1);
                            assert_eq!(report.observations.output_samples, 1);
                        } else {
                            assert_eq!(sink.chunks, 42);
                            assert_eq!(report.observations.output_samples, 42);
                        }
                        assert_eq!(
                            provider.series[0]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            9
                        );
                        for series in &provider.series[..42] {
                            assert!(
                                series
                                    .source
                                    .counters
                                    .samples_returned
                                    .load(Ordering::Relaxed)
                                    >= 17
                            );
                        }
                        assert_eq!(report.annotations.len(), 1);
                        drop(std::mem::take(&mut report.annotations));
                        report.observations = account.snapshot();
                        report.assert_retained_callback_error_memory();
                    }
                    println!(
                        "{{\"sort_emit_phase\":\"{phase}\",\"descending\":{descending},\"page_size\":{page},\"chunks\":{},\"first_acquisitions\":{},\"last_acquisitions\":{}}}",
                        sink.chunks,
                        provider.series[0]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed),
                        provider.series[42]
                            .source
                            .counters
                            .opened
                            .load(Ordering::Relaxed)
                    );
                    provider.assert_closed();
                    drop((report, query));
                    account.snapshot().assert_memory_released();
                    drop(account);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn sort_child_and_comparator_failures_precede_pending_duplicate_publication() {
        for page in [1, 17, 1024] {
            for function in ["sort", "sort_desc", "sort_by_label", "sort_by_label_desc"] {
                for phase in ["none", "scan", "compare"] {
                    if phase == "compare" && function.contains("by_label") {
                        continue;
                    }
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut provider = FixtureProvider::new(1, page, 43);
                    for (index, series) in provider.series.iter_mut().enumerate() {
                        let value = if index < 2 {
                            crate::test_storage::FULL_LABEL_HASH_COLLISION_VALUES[index].to_vec()
                        } else {
                            format!("unique{index}").into_bytes()
                        };
                        series.labels = vec![(b"a".to_vec(), value)];
                        // Separate counters establish each source's actual acquisition phase.
                        series.source.counters = Default::default();
                    }
                    let (target, acquisition) = if phase == "compare" { (20, 3) } else { (42, 2) };
                    if phase != "none" {
                        provider.series[target].source.fail_acquisition = Some(acquisition);
                    }
                    let expression = if function.contains("by_label") {
                        format!("{function}({{a=~\".+\"}},\"a\")")
                    } else {
                        format!("{function}({{a=~\".+\"}})")
                    };
                    let mut settings = EngineOptions::default();
                    settings.parser.experimental_functions = true;
                    let query = engine
                        .compile(expression.as_bytes(), settings, &control)
                        .unwrap();
                    let mut sink = RecordingSink::default();
                    let report = query.execute_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 1000 },
                        &control,
                        &mut sink,
                    );
                    if phase == "none" {
                        assert!(is_duplicate(report.result.as_ref().unwrap_err()));
                    } else {
                        assert!(matches!(
                            &report.result,
                            Err(ExecutionError::Evaluation(EvaluationError::Storage(
                                StorageError::Provider(bytes)
                            ))) if &**bytes == b"injected page failure"
                        ));
                        assert_eq!(
                            provider.series[target]
                                .source
                                .counters
                                .opened
                                .load(Ordering::Relaxed),
                            acquisition
                        );
                    }
                    for (index, series) in provider.series.iter().enumerate() {
                        let required = if phase == "scan" && index == target {
                            1
                        } else {
                            2
                        };
                        assert!(
                            series
                                .source
                                .counters
                                .samples_returned
                                .load(Ordering::Relaxed)
                                >= required
                        );
                    }
                    assert!(sink.begun && sink.aborted && !sink.committed);
                    assert_eq!(sink.chunks, 0);
                    assert_eq!(report.observations.output_samples, 0);
                    assert!(report.annotations.is_empty());
                    report.assert_retained_callback_error_memory();
                    provider.assert_closed();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn finite_signed_merged_matrix_output_preserves_sorted_lanes() {
        // A collided label group sorts its lanes before aliases publish the completed matrix.
        let left = "label_replace(vector(time()) == 0,\"src\",\"a\",\"__name__\",\".*\")";
        let right = "label_replace(vector(time()) < 0,\"src\",\"b\",\"__name__\",\".*\")";
        let merged = format!("label_replace({left} or {right},\"src\",\"x\",\"src\",\".*\")");
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for (body, negate) in [
                    (merged.clone(), false),
                    (format!("label_join({merged},\"x\",\"-\",\"src\")"), false),
                    (
                        format!("label_replace({merged},\"src\",\"x\",\"src\",\".*\")"),
                        false,
                    ),
                    (format!("-({merged})"), true),
                ] {
                    let provider = FixtureProvider::new(0, page, 0);
                    let engine = Engine::default();
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("({body})[2ms:]").as_bytes(),
                            EngineOptions {
                                no_step_subquery_interval_ms: -(1_i64 << 62),
                                ..options(delayed)
                            },
                            &control,
                        )
                        .unwrap();
                    let (output, observed) = query
                        .collect(&provider, QueryRequest::Instant { time_ms: 1 }, &control)
                        .unwrap();
                    assert_eq!(output.series.len(), 1, "{body}");
                    let points = &output.series[0].points;
                    assert_eq!(points.len(), 3, "{body}");
                    for (point, time) in points.iter().zip([i64::MIN, -(1_i64 << 62), 0]) {
                        assert_eq!(point.time_ms, time, "{body}");
                        let value = time as f64 / 1000.0;
                        assert_eq!(
                            float_bits(point),
                            if negate { -value } else { value }.to_bits(),
                            "{body}"
                        );
                    }
                    assert_eq!(observed.memory[MemoryKind::Workspace as usize].current, 0);
                    drop((output, query));
                    provider.assert_closed();
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn signed_direct_native_lanes_preserve_ties_hints_and_failure_cleanup() {
        use crate::{
            histogram::{FloatHistogram, Span},
            value::{Sample, SampleValue},
        };
        fn native(_: usize) -> Sample {
            Sample {
                time_ms: 0,
                start_time_ms: 0,
                value: SampleValue::FloatHistogram(FloatHistogram {
                    reset_hint: 3,
                    count: 4.0,
                    sum: 4.0,
                    positive_spans: Some(AccountedVec::from_iter_in(
                        [Span {
                            offset: 0,
                            length: 1,
                        }],
                        None,
                    )),
                    positive_buckets: Some(AccountedVec::from_iter_in([4.0], None)),
                    ..FloatHistogram::default()
                }),
            }
        }
        let left = "label_replace(vector(time()),\"source\",\"a\",\"__name__\",\".*\")";
        let right = "label_replace(h,\"source\",\"b\",\"__name__\",\".*\")";
        let merged = format!(
            "label_replace(label_replace({left} or {right},\"__name__\",\"\",\"__name__\",\".*\"),\"source\",\"x\",\"source\",\".*\")"
        );
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for (body, negate) in [
                    (merged.clone(), false),
                    (format!("label_join({merged},\"x\",\"-\",\"source\")"), false),
                    (format!("-({merged})"), true),
                    (
                        "-(label_replace(vector(time()),\"__name__\",\"a\",\"__name__\",\".*\") or on(__name__) h)"
                            .to_owned(),
                        true,
                    ),
                ] {
                    let mut provider = FixtureProvider::new(1, page, 1);
                    provider.series[0].labels = vec![(b"__name__".to_vec(), b"h".to_vec())];
                    provider.series[0].source.sample = native;
                    let engine = Engine::default();
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("({body})[2ms:]").as_bytes(),
                            EngineOptions {
                                no_step_subquery_interval_ms: -(1_i64 << 62),
                                ..options(delayed)
                            },
                            &control,
                        )
                        .unwrap();
                    let (output, observed) = query
                        .collect(&provider, QueryRequest::Instant { time_ms: 1 }, &control)
                        .unwrap();
                    assert_eq!(output.series.len(), 1, "{body}/{delayed}");
                    let points = &output.series[0].points;
                    assert_eq!(points.len(), 4, "{body}/{delayed}");
                    for (point, time) in points[..3].iter().zip([i64::MIN, -(1_i64 << 62), 0]) {
                        assert_eq!(point.time_ms, time, "{body}/{delayed}");
                        let value = time as f64 / 1000.0;
                        assert_eq!(
                            float_bits(point),
                            if negate { -value } else { value }.to_bits(),
                            "{body}/{delayed}"
                        );
                    }
                    assert_eq!(points[3].time_ms, 0);
                    let OwnedValue::Histogram(histogram) = &points[3].value else {
                        panic!("expected histogram after the equal-time float");
                    };
                    let histogram = histogram.as_ref();
                    assert_eq!(histogram.reset_hint, 3);
                    let count: f64 = if negate { -4.0 } else { 4.0 };
                    let zero: f64 = if negate { -0.0 } else { 0.0 };
                    assert_eq!(histogram.count.to_bits(), count.to_bits());
                    assert_eq!(histogram.sum.to_bits(), count.to_bits());
                    assert_eq!(histogram.zero_count.to_bits(), zero.to_bits());
                    assert_eq!(histogram.positive_buckets.as_ref().unwrap()[0], count);
                    assert_eq!(observed.memory[MemoryKind::Workspace as usize].current, 0);
                    drop(output);
                    for mode in 1..=3 {
                        let control = Control::default();
                        let mut sink = RecordingSink {
                            fail_after: (mode == 1).then_some(4),
                            cancel: (mode == 2).then(|| control.cancellation.clone()),
                            panic_after: (mode == 3).then_some(4),
                            ..RecordingSink::default()
                        };
                        let report = query.execute_reported(
                            &provider,
                            QueryRequest::Instant { time_ms: 1 },
                            &control,
                            &mut sink,
                        );
                        assert!(report.result.is_err());
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        if mode == 2 {
                            assert!(matches!(
                                report.result,
                                Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                                    Interrupted::Cancelled
                                )))
                            ));
                        } else if mode == 3 {
                            assert!(matches!(report.result, Err(ExecutionError::Internal)));
                        }
                        provider.assert_closed();
                        assert_eq!(engine.accounting.snapshot().active_executions, 0);
                    }
                    assert_eq!(provider.series[0].source.counters.peak.load(Ordering::Relaxed), 1);
                    drop(query);
                    provider.assert_closed();
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn signed_matrix_parents_consume_sorted_heads_by_caller_position() {
        // Merged label groups sort their lanes; a mismatched head stays blocked.
        let left = "label_replace(vector(time()) == 0,\"src\",\"a\",\"__name__\",\".*\")";
        let right = "label_replace(vector(time()) < 0,\"src\",\"b\",\"__name__\",\".*\")";
        let merged = format!("label_replace({left} or {right},\"src\",\"x\",\"src\",\".*\")");
        let provider = FixtureProvider::new(0, 1, 0);
        for (parent, positive) in [
            (format!("abs({merged})"), true),
            (format!("sum({merged})"), false),
            (
                format!("abs(label_join({merged},\"x\",\"-\",\"src\"))"),
                true,
            ),
            (format!("abs(-({merged}))"), true),
        ] {
            let engine = Engine::default();
            let control = Control::default();
            let expression = format!("({parent})[2ms:]");
            let query = engine
                .compile(
                    expression.as_bytes(),
                    EngineOptions {
                        no_step_subquery_interval_ms: -(1_i64 << 62),
                        ..EngineOptions::default()
                    },
                    &control,
                )
                .unwrap();
            let (output, _) = query
                .collect(&provider, QueryRequest::Instant { time_ms: 1 }, &control)
                .unwrap();
            assert_eq!(output.series.len(), 1, "{expression}");
            let points = &output.series[0].points;
            assert_eq!(points.len(), 1, "{expression}");
            assert_eq!(points[0].time_ms, i64::MIN, "{expression}");
            let value = i64::MIN as f64 / 1000.0;
            assert_eq!(
                float_bits(&points[0]),
                if positive { value.abs() } else { value }.to_bits(),
                "{expression}"
            );
            provider.assert_closed();
            drop((output, query));
            engine.accounting.snapshot().assert_memory_released();
        }
    }

