    #[test]
    fn range_helper_errors_follow_series_before_step_order() {
        use crate::value::{Sample, SampleValue};
        fn late(_: usize) -> Sample {
            Sample {
                time_ms: 5000,
                start_time_ms: 0,
                value: SampleValue::Float(7.0),
            }
        }
        fn early(index: usize) -> Sample {
            Sample {
                time_ms: 1000,
                ..late(index)
            }
        }
        for page in [1, 17, 1024] {
            for late_first in [true, false] {
                let mut provider = FixtureProvider::new(1, page, 2);
                provider.series[0].source.sample = if late_first { late } else { early };
                provider.series[1].source.sample = if late_first { early } else { late };
                let engine = Engine::default();
                let control = Control::default();
                let options = EngineOptions {
                    parser: ParserOptions {
                        experimental_functions: true,
                        ..ParserOptions::default()
                    },
                    ..EngineOptions::default()
                };
                for (parameters, factor, name) in [
                    ("time(),0.5", "sf", "smoothing"),
                    ("0.5,time()", "tf", "trend"),
                    ("time(),time()", "sf", "smoothing"),
                    (
                        "1.1-time()/10,time()",
                        if late_first { "tf" } else { "sf" },
                        if late_first { "trend" } else { "smoothing" },
                    ),
                ] {
                    let expression =
                        format!("double_exponential_smoothing(counter_total[500ms],{parameters})");
                    let query = engine
                        .compile(expression.as_bytes(), options, &control)
                        .unwrap();
                    let error = query
                        .collect(
                            &provider,
                            QueryRequest::Range {
                                start_ms: 1000,
                                end_ms: 5000,
                                step_ms: 1000,
                            },
                            &control,
                        )
                        .unwrap_err();
                    let ExecutionError::Evaluation(EvaluationError::Runtime(message)) = &error
                    else {
                        panic!("{error:?}");
                    };
                    let expected = format!(
                        "invalid {name} factor. Expected: 0 < {factor} < 1, got: {:.6}",
                        if late_first { 5.0 } else { 1.0 }
                    );
                    assert_eq!(&message[..], expected.as_bytes());
                    drop(error);
                    drop(query);
                    provider.assert_closed();
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn completed_set_preparation_clears_discovery_before_both_final_routes() {
        let body = "label_replace(counter_total,\"branch\",\"a\",\"instance\",\".*\") or label_replace(counter_total,\"branch\",\"b\",\"instance\",\".*\")";
        for (derived, request) in [
            (false, QueryRequest::Instant { time_ms: 4000 }),
            (
                false,
                QueryRequest::Range {
                    start_ms: 4000,
                    end_ms: 4000,
                    step_ms: 1000,
                },
            ),
            (
                false,
                QueryRequest::Range {
                    start_ms: 4000,
                    end_ms: 4001,
                    step_ms: 1000,
                },
            ),
            (
                false,
                QueryRequest::Range {
                    start_ms: 2000,
                    end_ms: 4000,
                    step_ms: 1000,
                },
            ),
            (true, QueryRequest::Instant { time_ms: 4000 }),
        ] {
            let expression = if derived {
                format!("({body})[3s:1s]")
            } else {
                format!("sum({body})")
            };
            for page in [1, 17, 1024] {
                let provider = FixtureProvider::new(4, page, 4);
                let engine = Engine::default();
                let control = Control::default();
                let compiled = engine
                    .compile(expression.as_bytes(), EngineOptions::default(), &control)
                    .unwrap();
                let account = engine.accounting.query();
                {
                    let header = compiled.header(request).unwrap();
                    let prepared = Prepared::new(
                        &compiled.expression,
                        &compiled.preprocessing,
                        header,
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let bounds = crate::query_bounds::find(
                        &compiled.expression,
                        compiled.evaluation_options(header, header.start_ms, &prepared),
                        &prepared,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let query = provider.open(bounds, &control).unwrap();
                    let catalog = Catalog::new(
                        &query,
                        &compiled.expression,
                        &prepared,
                        compiled.evaluation_options(header, header.start_ms, &prepared),
                        compiled.options.no_step_subquery_interval_ms,
                        &control,
                        &account,
                    )
                    .unwrap();
                    let rosters = compiled
                        .prepare_rosters(
                            &catalog,
                            &prepared,
                            bounds,
                            &control,
                            &account,
                            &mut Annotations::default(),
                        )
                        .unwrap();
                    let mut certified = 0;
                    for position in 0..compiled.expression.arena.nodes.len() {
                        if let Some(plan) = rosters.binary(NodeId(position))
                            && plan.has_set_discovery()
                        {
                            certified += 1;
                            assert!(!plan.has_completed_set_discovery());
                        }
                    }
                    assert!(
                        certified > 0,
                        "derived={derived},request={request:?},page={page}"
                    );
                }
                provider.assert_closed();
                account.snapshot().assert_memory_released();
                drop((compiled, account));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
