    #[test]
    fn nested_selection_reuses_ready_parameters_without_the_known_cardinality_factor() {
        fn one(_: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(1.0),
            }
        }
        for operator in ["topk", "bottomk", "limitk", "limit_ratio"] {
            let mut reads = Vec::new();
            for depth in [1, 4] {
                let mut provider = FixtureProvider::new(1, 1, 24);
                for series in &mut provider.series {
                    series.source.sample = one;
                }
                let engine = Engine::default();
                let control = Control::default();
                let parameter = if operator == "limit_ratio" { "-1" } else { "5" };
                let mut source = format!("{operator}({parameter},counter_total)");
                for _ in 0..depth {
                    source = if operator == "limit_ratio" {
                        format!("{operator}(-scalar(sum({source}))/24,counter_total)")
                    } else {
                        format!("{operator}(scalar(sum({source})),counter_total)")
                    };
                }
                let mut settings = EngineOptions::default();
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                let (result, observed) = query
                    .collect(&provider, QueryRequest::Instant { time_ms: 1000 }, &control)
                    .unwrap();
                assert_eq!(
                    result.series.len(),
                    if operator == "limit_ratio" { 24 } else { 5 }
                );
                assert!(
                    result
                        .series
                        .iter()
                        .all(|row| float_bits(&row.points[0]) == 1.0_f64.to_bits())
                );
                reads.push(observed.samples_fetched);
                provider.assert_closed();
                assert_eq!(
                    provider.series[0]
                        .source
                        .counters
                        .peak
                        .load(Ordering::Relaxed),
                    1
                );
                drop((result, query));
                engine.accounting.snapshot().assert_memory_released();
            }
            // This producer class rules out its known repeated-parameter factor, not every expression shape.
            assert!(reads[1] < reads[0] * 6, "{operator}: {reads:?}");
        }
    }

    #[test]
    fn histogram_preprocessing_stops_before_enqueuing_cancelled_variadic_arguments() {
        let engine = Engine::default();
        let control = Control::default();
        let mut source = "(".repeat(8191);
        source.push_str("label_join(counter_total,\"destination\",\",\"");
        for _ in 0..10_000 {
            source.push_str(",\"id\"");
        }
        source.push(')');
        source.push_str(&")".repeat(8191));
        let mut query = engine
            .compile(source.as_bytes(), EngineOptions::default(), &control)
            .unwrap();
        let account = engine.accounting.query();
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            crate::histogram_stats::configure(&mut query.expression, &control, &account)
        });
        assert_eq!(result, Err(Interrupted::Cancelled));
        let observed = account.snapshot();
        assert_eq!(observed.work, 8192);
        assert!(
            observed.memory[MemoryKind::Workspace as usize].peak
                < (100 * size_of::<(NodeId, bool, bool)>()) as u64,
            "pending cancellation must precede the variable argument task allocation: {observed:?}"
        );
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn failed_selection_positions_account_work_without_replacing_provider_error() {
        use crate::storage::{
            ProviderDiagnosticRef, ProviderResources, SelectionRequest, SeriesSelection,
        };
        #[derive(Clone, Copy)]
        struct FailedSelection {
            position: usize,
        }
        impl Provider for FailedSelection {
            type Query<'a> = Self;
            fn open(&self, _: TimeBounds, _: &Control) -> Result<Self, StorageError> {
                Ok(*self)
            }
        }
        impl QueryProvider for FailedSelection {
            type Selection<'a> = Self;
            fn resources(&self) -> ProviderResources {
                ProviderResources::default()
            }
            fn select(&self, _: SelectionRequest<'_>, _: &Control) -> Result<Self, StorageError> {
                Ok(*self)
            }
        }
        impl SeriesSelection for FailedSelection {
            type Series = crate::test_storage::FixtureHandle<'static>;
            fn resources(&self) -> ProviderResources {
                ProviderResources::default()
            }
            fn next(&mut self, control: &Control) -> Result<Option<Self::Series>, StorageError> {
                control.cancellation.cancel();
                Err(StorageError::Provider(b"selection failure".to_vec().into()))
            }
            fn diagnostic_count(&self) -> usize {
                1
            }
            fn diagnostic<R>(
                &self,
                _: usize,
                visit: impl for<'a> FnOnce(ProviderDiagnosticRef<'a>) -> R,
            ) -> R {
                visit(ProviderDiagnosticRef {
                    message: b"",
                    severity: crate::annotations::Severity::Info,
                    position: Some(crate::frontend::Span {
                        start: self.position,
                        end: self.position,
                    }),
                })
            }
        }
        let engine = Engine::default();
        let source = format!("{}counter_total", " ".repeat(32_768));
        let query = engine
            .compile(
                source.as_bytes(),
                EngineOptions::default(),
                &Control::default(),
            )
            .unwrap();
        let mut work = Vec::new();
        for position in [0, 32_768] {
            let control = Control::default();
            let account = query.execution_accounting();
            let report = query.collect_reported_in(
                &FailedSelection { position },
                QueryRequest::Instant { time_ms: 0 },
                &control,
                &account,
            );
            assert!(control.cancellation.cancelled());
            let Err(ExecutionError::Evaluation(EvaluationError::Expansion(error))) = &report.result
            else {
                panic!("the completed selection error must precede cancellation")
            };
            assert_eq!(&**error, b"expanding series: selection failure");
            let note = report
                .annotations
                .iter()
                .next()
                .expect("positioned diagnostic");
            assert!(note.raw_message.is_empty());
            assert_eq!(note.message, format!(" (1:{})", position + 1).as_bytes());
            assert_eq!(note.span.unwrap().start, position);
            work.push(report.observations.work);
            drop(report);
            account.snapshot().assert_memory_released();
        }
        assert!(
            work[1] - work[0] >= 32_768,
            "visited prefix bytes must be charged after a completed error: {work:?}"
        );
        drop(query);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn parenthesis_projection_reports_work_and_observes_cancellation() {
        use crate::storage::Interrupted;
        let engine = Engine::default();
        let control = Control::default();
        let source = format!(
            "sum({}counter_total{})",
            "(".repeat(10_000),
            ")".repeat(10_000)
        );
        let query = engine
            .compile(source.as_bytes(), EngineOptions::default(), &control)
            .unwrap();
        let Expr::Aggregate {
            expression: Some(argument),
            ..
        } = query.expression.arena[query.expression.root].expression
        else {
            panic!("aggregate argument");
        };
        let account = engine.accounting.query();
        let before = account.snapshot().work;
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            let child = query.preprocessing.child(
                &query.expression,
                query.expression.root,
                argument,
                &control,
                &account,
            )?;
            control.check()?;
            Ok(child)
        });
        assert_eq!(result, Err(Interrupted::Cancelled));
        assert!(account.snapshot().work - before < 10_000);
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn skipped_variadic_string_children_poll_without_collecting_a_second_task_array() {
        use crate::storage::Interrupted;
        let engine = Engine::default();
        let control = Control::default();
        let mut source = b"sort_by_label(counter_total".to_vec();
        for _ in 0..10_000 {
            source.extend_from_slice(b",\"id\"");
        }
        source.push(b')');
        let query = engine
            .compile(
                &source,
                EngineOptions {
                    parser: ParserOptions {
                        experimental_functions: true,
                        ..ParserOptions::default()
                    },
                    ..options(true)
                },
                &control,
            )
            .unwrap();
        let account = engine.accounting.query();
        let header = query
            .header(QueryRequest::Instant { time_ms: 1000 })
            .unwrap();
        let prepared = Prepared::new(
            &query.expression,
            &query.preprocessing,
            header,
            query.options.no_step_subquery_interval_ms,
            &control,
            &account,
        )
        .unwrap();
        let before = account.snapshot().work;
        let result = crate::test_storage::interrupt_during(&account, &control, || {
            children(
                &query.expression,
                &prepared,
                query.expression.root,
                &control,
                &account,
            )
            .expect("typed child projection")
            .next_back()
        });
        assert!(matches!(result, Some(Err(Interrupted::Cancelled))));
        assert_eq!(account.snapshot().work - before, 8192);
        drop(prepared);
        drop(query);
        account.snapshot().assert_memory_released();
        drop(account);
        engine.accounting.snapshot().assert_memory_released();
    }

    #[test]
    fn cancellation_in_label_callbacks_stops_each_metadata_walk_and_releases_owners() {
        use crate::{storage::Interrupted, test_storage::observe_label_reads};
        const LABELS: usize = 4096;
        for source in [
            &b"counter_total"[..],
            b"counter_total[2s]",
            b"rate(counter_total[2s])",
            b"sum(counter_total)",
            b"scalar(counter_total)",
        ] {
            let mut provider = FixtureProvider::new(2, 1, 1);
            for index in 2..LABELS {
                provider.series[0]
                    .labels
                    .push((format!("z{index:05}").into_bytes(), b"v".to_vec()));
            }
            let engine = Engine::default();
            let control = Control::default();
            let query = engine.compile(source, options(true), &control).unwrap();
            let mut sink = RecordingSink::default();
            let (result, reads) = observe_label_reads(&control, None, || {
                query.execute(
                    &provider,
                    QueryRequest::Instant { time_ms: 2000 },
                    &control,
                    &mut sink,
                )
            });
            result.unwrap();
            assert!(reads >= LABELS);
            provider.assert_closed();
            drop((query, sink));
            engine.accounting.snapshot().assert_memory_released();
            for cancel_at in (2..reads).step_by(provider.series[0].labels.len()) {
                let control = Control::default();
                let query = engine.compile(source, options(true), &control).unwrap();
                let mut sink = RecordingSink::default();
                let (result, observed) = observe_label_reads(&control, Some(cancel_at), || {
                    query.execute(
                        &provider,
                        QueryRequest::Instant { time_ms: 2000 },
                        &control,
                        &mut sink,
                    )
                });
                let error = result.unwrap_err();
                assert!(matches!(
                    error,
                    ExecutionError::Evaluation(EvaluationError::Interrupted(
                        Interrupted::Cancelled
                    )) | ExecutionError::Evaluation(EvaluationError::Storage(
                        StorageError::Interrupted(Interrupted::Cancelled)
                    ))
                ));
                assert!(sink.begun && sink.aborted && !sink.committed);
                provider.assert_closed();
                drop((error, query, sink));
                engine.accounting.snapshot().assert_memory_released();
                assert_eq!(
                    observed,
                    cancel_at,
                    "{}: cancellation callback must end this walk",
                    String::from_utf8_lossy(source)
                );
            }
        }
    }

    #[test]
    fn selection_comparison_cancellation_and_partial_output_release_all_owners() {
        use crate::storage::{Cancellation, Interrupted};
        thread_local! {
            static GATE: std::cell::RefCell<Option<(Cancellation, usize)>> = const { std::cell::RefCell::new(None) };
        }
        fn sample(index: usize) -> crate::value::Sample {
            GATE.with_borrow_mut(|gate| {
                if let Some((cancellation, reads)) = gate {
                    *reads += 1;
                    if *reads == 30 {
                        cancellation.cancel();
                    }
                }
            });
            crate::test_storage::counter(index)
        }
        fn native_sample(index: usize) -> crate::value::Sample {
            let mut point = sample(index);
            point.value =
                crate::value::SampleValue::FloatHistogram(crate::histogram::FloatHistogram {
                    schema: -53,
                    count: 3.0,
                    sum: 5.0,
                    zero_count: 7.0,
                    positive_buckets: Some(vec![1.0, 2.0].into()),
                    custom_values: Some(vec![1.0].into()),
                    ..crate::histogram::FloatHistogram::default()
                });
            point
        }
        for (operator, native) in [
            ("topk", false),
            ("bottomk", false),
            ("limitk", false),
            ("limit_ratio", false),
            ("limitk", true),
            ("limit_ratio", true),
        ] {
            for cancel in [false, true] {
                let mut provider = FixtureProvider::new(1, 1, 8);
                for series in &mut provider.series {
                    series.source.sample = if native { native_sample } else { sample };
                }
                let engine = Engine::default();
                let control = Control::default();
                let parameter = if operator == "limit_ratio" { "-1" } else { "8" };
                let source = format!("{operator}({parameter},counter_total)");
                let mut settings = EngineOptions::default();
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                let mut sink = RecordingSink {
                    fail_after: (!cancel).then_some(2),
                    ..RecordingSink::default()
                };
                if cancel {
                    GATE.with_borrow_mut(|gate| *gate = Some((control.cancellation.clone(), 0)));
                }
                let error = query
                    .execute(
                        &provider,
                        QueryRequest::Instant { time_ms: 1000 },
                        &control,
                        &mut sink,
                    )
                    .unwrap_err();
                if cancel {
                    assert_eq!(GATE.with_borrow_mut(|gate| gate.take().unwrap().1), 30);
                    assert!(matches!(
                        error,
                        ExecutionError::Evaluation(EvaluationError::Interrupted(
                            Interrupted::Cancelled
                        )) | ExecutionError::Evaluation(EvaluationError::Storage(
                            StorageError::Interrupted(Interrupted::Cancelled)
                        ))
                    ));
                } else {
                    assert!(matches!(error, ExecutionError::Sink(_)));
                }
                assert!(sink.begun && sink.aborted && !sink.committed);
                provider.assert_closed();
                drop((error, query, sink));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn info_checks_native_samples_without_a_simultaneous_base_but_skips_empty_step_join_duplicates()
    {
        use crate::{
            histogram::FloatHistogram,
            value::{STALE_NAN_BITS, Sample, SampleValue},
        };
        fn base(index: usize) -> Sample {
            Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 77,
                value: SampleValue::Float(if index == 0 {
                    f64::from_bits(STALE_NAN_BITS)
                } else {
                    42.0
                }),
            }
        }
        fn native_then_float(index: usize) -> Sample {
            Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: if index == 0 {
                    SampleValue::FloatHistogram(FloatHistogram::default())
                } else {
                    SampleValue::Float(1.0)
                },
            }
        }
        for native in [false, true] {
            let mut provider = FixtureProvider::new(2, 1, 3);
            provider.series[0].source.sample = base;
            for (index, series) in provider.series.iter_mut().enumerate().skip(1) {
                series.labels = vec![
                    (b"__name__".to_vec(), b"target_info".to_vec()),
                    (b"data".to_vec(), index.to_string().into_bytes()),
                    (b"instance".to_vec(), b"0".to_vec()),
                    (b"job".to_vec(), b"worker".to_vec()),
                ];
            }
            provider.series[1].source.count = 1;
            if native {
                provider.series[2].source.sample = native_then_float;
            }
            let engine = Engine::default();
            let control = Control::default();
            let mut settings = EngineOptions::default();
            settings.parser.experimental_functions = true;
            let query = engine
                .compile(b"info(counter_total)", settings, &control)
                .unwrap();
            let report = query.collect_reported(
                &provider,
                QueryRequest::Range {
                    start_ms: 1000,
                    end_ms: 2000,
                    step_ms: 1000,
                },
                &control,
            );
            if native {
                assert!(
                    matches!(&report.result, Err(ExecutionError::Evaluation(EvaluationError::Runtime(bytes))) if bytes.starts_with(b"this should be an info metric, with float samples:"))
                );
            } else {
                let output = report.result.as_ref().unwrap();
                assert_eq!(
                    report
                        .observations
                        .statistics
                        .samples
                        .total_queryable_samples,
                    5,
                    "the implicit info selector participates before base/winner filtering",
                );
                assert_eq!(output.series.len(), 1);
                assert_eq!(output.series[0].points.len(), 1);
                assert_eq!(output.series[0].points[0].time_ms, 2000);
                assert_eq!(float_bits(&output.series[0].points[0]), 42.0_f64.to_bits());
                assert!(
                    output.series[0]
                        .labels
                        .0
                        .iter()
                        .any(|label| label.name == b"data" && label.value == b"2")
                );
            }
            provider.assert_closed();
            drop((report, query));
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    fn mapped_group_provider(page: usize, groups: usize) -> FixtureProvider {
        fn counter<const SCALE: u64>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float((index as u64 + 1) as f64 * SCALE as f64),
            }
        }
        let mut provider = FixtureProvider::new(5, page, groups * 2);
        for (index, series) in provider.series.iter_mut().enumerate() {
            let group = groups - 1 - index / 2;
            series.labels = vec![
                (b"__name__".to_vec(), b"counter_total".to_vec()),
                (b"instance".to_vec(), format!("g{group:04}").into_bytes()),
                (b"member".to_vec(), (index % 2).to_string().into_bytes()),
            ];
            series.source.sample = if group.is_multiple_of(2) {
                counter::<1>
            } else {
                counter::<2>
            };
            series.source.counters = Default::default();
        }
        provider
    }

    #[test]
    fn aggregate_label_borrows_outlive_machines_and_materialize_at_descriptor_boundaries() {
        use crate::{evaluator::EvaluatedSample, sample_labels::SampleLabels};

        for (expression, expected_labels, value_factor) in [
            ("abs(sum by(instance)(counter_total))", 1, 1.0),
            ("topk(2,sum by(instance)(counter_total))", 1, 1.0),
            ("bottomk(2,sum by(instance)(counter_total))", 1, 1.0),
            ("abs(topk(2,sum by(instance)(counter_total)))", 1, 1.0),
            (
                "label_join(topk(2,sum by(instance)(counter_total)), \"row\", \"/\", \"instance\")",
                2,
                1.0,
            ),
            (
                "label_join(abs(sum by(instance)(counter_total)), \"row\", \"/\", \"instance\")",
                2,
                1.0,
            ),
            (
                "sum by(instance)(counter_total) + on(instance) sum by(instance)(counter_total)",
                1,
                2.0,
            ),
            (
                "sum by(instance)(counter_total) or sum by(instance)(counter_total)",
                1,
                1.0,
            ),
            ("quantile by(instance)(0.5,counter_total)", 1, 0.5),
            ("abs(quantile by(instance)(0.5,counter_total))", 1, 0.5),
            (
                "label_join(quantile by(instance)(0.5,counter_total), \"row\", \"/\", \"instance\")",
                2,
                0.5,
            ),
        ] {
            for delayed in [false, true] {
                for page in [1, 17, 1024] {
                    let (collected, retained) = {
                        let input = mapped_group_provider(page, 2);
                        let engine = Engine::default();
                        let control = Control::default();
                        let query = engine
                            .compile(expression.as_bytes(), options(delayed), &control)
                            .unwrap();
                        let request = QueryRequest::Range {
                            start_ms: 1000,
                            end_ms: 2000,
                            step_ms: 1000,
                        };
                        let account = query.execution_accounting();
                        {
                            let header = query.header(request).unwrap();
                            let prepared = Prepared::new(
                                &query.expression,
                                &query.preprocessing,
                                header,
                                query.options.no_step_subquery_interval_ms,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let header = prepared.evaluator_header();
                            prepared.activate(header, &control, &account).unwrap();
                            let options =
                                query.evaluation_options(header, header.start_ms, &prepared);
                            let bounds = crate::query_bounds::find(
                                &query.expression,
                                options,
                                &prepared,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let scope = input.open(bounds, &control).unwrap();
                            let catalog = Catalog::new(
                                &scope,
                                &query.expression,
                                &prepared,
                                options,
                                query.options.no_step_subquery_interval_ms,
                                &control,
                                &account,
                            )
                            .unwrap();
                            let rosters = query
                                .prepare_rosters(
                                    &catalog,
                                    &prepared,
                                    bounds,
                                    &control,
                                    &account,
                                    &mut Annotations::default(),
                                )
                                .unwrap();
                            let metadata = || EvaluationMetadata {
                                prepared: &prepared,
                                rosters: &rosters,
                                timestamp_selectors: &query.timestamp_selectors,
                                data_bounds: bounds,
                                annotations: None,
                                binary_preparation: None,
                                histogram_preparation: None,
                                info_preparation: None,
                                count_preparation: None,
                            };
                            let mut machine = Machine::new(
                                &catalog,
                                &query.expression,
                                query.expression.root,
                                options,
                                &control,
                                &account,
                                metadata(),
                            );
                            let first = machine.next().unwrap().unwrap();
                            let second = machine.next().unwrap().unwrap();
                            assert!(machine.next().unwrap().is_none());
                            drop(machine);
                            assert!(
                                matches!(first.labels, SampleLabels::Borrowed(_)),
                                "immutable result labels must borrow their frozen owner: {expression}"
                            );
                            assert!(matches!(second.labels, SampleLabels::Borrowed(_)));
                            assert_eq!(first.labels.0.len(), expected_labels);
                            if expected_labels == 2 {
                                assert_eq!(first.labels.0[1].name.as_ref(), b"row");
                                assert_eq!(first.labels.0[1].value, first.labels.0[0].value);
                                rosters.clear_replay_progress(&control, &account).unwrap();
                                prepared.range_folds.clear(&control, &account).unwrap();
                                let mut calibration = Machine::new(
                                    &catalog,
                                    &query.expression,
                                    query.expression.root,
                                    options,
                                    &control,
                                    &account,
                                    metadata(),
                                );
                                calibration.bypass_root_order();
                                let before = account.snapshot().work;
                                assert!(calibration.next().unwrap().is_some());
                                let final_work = account.snapshot().work - before;
                                assert!(final_work > 0);
                                drop(calibration);
                                rosters.clear_replay_progress(&control, &account).unwrap();
                                prepared.range_folds.clear(&control, &account).unwrap();
                                let cancelled = Control::default();
                                let mut interrupted = Machine::new(
                                    &catalog,
                                    &query.expression,
                                    query.expression.root,
                                    options,
                                    &cancelled,
                                    &account,
                                    metadata(),
                                );
                                interrupted.bypass_root_order();
                                let before = account.snapshot().work;
                                let result = crate::test_storage::interrupt_after_work(
                                    &account,
                                    &cancelled,
                                    final_work,
                                    || interrupted.next(),
                                );
                                assert_eq!(account.snapshot().work - before, final_work);
                                assert_eq!(
                                    result.map(|_| ()),
                                    Err(EvaluationError::Interrupted(Interrupted::Cancelled))
                                );
                                drop(interrupted);
                            }
                            assert_eq!(first.labels.0[0].name.as_ref(), b"instance");
                            assert_ne!(first.labels.0[0].value, second.labels.0[0].value);

                            let hash =
                                crate::label_hash::full(&first.labels, &control, &account).unwrap();
                            let make_sample = || EvaluatedSample {
                                ordinal: first.ordinal,
                                labels: SampleLabels::Borrowed(first.labels.as_ref()),
                                value: OwnedValue::Float(1.0),
                                float_samples: None,
                                source_time_ms: first.source_time_ms,
                                source_start_time_ms: 0,
                                drop_name: first.drop_name,
                            };
                            let record =
                                |descriptors: &mut AccountedVec<Descriptor>,
                                 index: &mut DescriptorIndex,
                                 control: &Control| {
                                    query.record_descriptor(
                                        query.expression.root,
                                        (make_sample(), hash),
                                        (descriptors, index),
                                        (&prepared, &rosters),
                                        control,
                                        &account,
                                    )
                                };
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            let before = account.snapshot().work;
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            let conversion_work = account.snapshot().work - before;
                            assert!(conversion_work > 0);
                            assert_eq!(descriptors.len(), 1);
                            assert!(descriptors[0].labels.same(&first.labels));
                            assert_ne!(descriptors[0].labels.0.as_ptr(), first.labels.0.as_ptr());
                            let before = account.snapshot().memory;
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            assert_eq!(
                                account.snapshot().memory,
                                before,
                                "existing descriptor must not copy labels"
                            );
                            drop((descriptors, index));

                            let before = account.snapshot().memory;
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            let cancelled = Control::default();
                            let error = crate::test_storage::interrupt_after_work(
                                &account,
                                &cancelled,
                                conversion_work,
                                || record(&mut descriptors, &mut index, &cancelled),
                            )
                            .unwrap_err();
                            assert_eq!(error, EvaluationError::Interrupted(Interrupted::Cancelled));
                            assert!(descriptors.is_empty());
                            // The provisional index exists before conversion; failure discards the whole local owner.
                            let probe = account.snapshot().work;
                            assert!(
                                index
                                    .find(
                                        first.ordinal + 1,
                                        &first.labels,
                                        &descriptors,
                                        &control,
                                        &account
                                    )
                                    .unwrap()
                                    .is_none()
                            );
                            assert!(account.snapshot().work > probe);
                            drop((descriptors, index));
                            assert!(
                                account
                                    .snapshot()
                                    .memory
                                    .iter()
                                    .zip(before)
                                    .all(|(now, old)| now.current == old.current)
                            );
                            let mut descriptors =
                                AccountedVec::new(&account, MemoryKind::Workspace);
                            let mut index = DescriptorIndex::new(&account);
                            assert_eq!(record(&mut descriptors, &mut index, &control).unwrap(), 0);
                            assert!(descriptors[0].labels.same(&first.labels));
                        }
                        input.assert_closed();
                        account.snapshot().assert_memory_released();
                        drop(account);
                        let (result, _) = query.collect(&input, request, &control).unwrap();
                        input.assert_closed();
                        (result, engine.accounting.clone())
                    };
                    assert_eq!(collected.series.len(), 2);
                    for (group, row) in collected.series.iter().enumerate() {
                        assert_eq!(
                            row.labels.0[0].value.as_ref(),
                            format!("g{group:04}").as_bytes()
                        );
                        assert_eq!(row.labels.0.len(), expected_labels);
                        if expected_labels == 2 {
                            assert_eq!(row.labels.0[1].name.as_ref(), b"row");
                            assert_eq!(row.labels.0[1].value, row.labels.0[0].value);
                        }
                        assert_eq!(row.points.len(), 2);
                        for (tick, point) in row.points.iter().enumerate() {
                            assert_eq!(point.time_ms, (tick as i64 + 1) * 1000);
                            assert_eq!(
                                float_bits(point),
                                (value_factor * 2.0 * (group + 1) as f64 * (tick + 1) as f64)
                                    .to_bits()
                            );
                        }
                    }
                    drop(collected);
                    retained.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn projected_groups_check_complete_results_before_bounded_source_reads() {
        let mut scaling = Vec::new();
        let mut complete = 0;
        for delayed in [false, true] {
            for page in [1, 17, 1024] {
                for window in [false, true] {
                    let body = if window {
                        "rate(counter_total[3s])"
                    } else {
                        "counter_total"
                    };
                    let aggregate = format!("sum by(instance)({body})");
                    let join = format!("label_join({aggregate},\"row\",\"/\",\"instance\")");
                    let replace =
                        format!("label_replace({aggregate},\"row\",\"$1\",\"instance\",\"(.*)\")");
                    let expressions = [
                        join.clone(),
                        replace.clone(),
                        format!("abs({join})"),
                        format!("label_join({replace},\"alias\",\"/\",\"instance\")"),
                    ];
                    for (request_index, request) in [
                        QueryRequest::Instant { time_ms: 3000 },
                        QueryRequest::Range {
                            start_ms: 3000,
                            end_ms: 3000,
                            step_ms: 1000,
                        },
                        QueryRequest::Range {
                            start_ms: 3000,
                            end_ms: 5000,
                            step_ms: 1000,
                        },
                    ]
                    .into_iter()
                    .enumerate()
                    {
                        for (shape, expression) in expressions.iter().enumerate() {
                            let mut reads = Vec::new();
                            for groups in [2, 4, 8, 16] {
                                let provider = mapped_group_provider(page, groups);
                                let engine = Engine::default();
                                let control = Control::default();
                                let query = engine
                                    .compile(expression.as_bytes(), options(delayed), &control)
                                    .unwrap();
                                let report = query.collect_reported(&provider, request, &control);
                                let result = report.result.as_ref().unwrap();
                                assert!(report.annotations.is_empty());
                                assert_eq!(result.series.len(), groups);
                                let points = if request_index == 2 { 3 } else { 1 };
                                let mut seen = vec![false; groups];
                                for (position, row) in result.series.iter().enumerate() {
                                    let instance = row
                                        .labels
                                        .0
                                        .iter()
                                        .find(|label| &*label.name == b"instance")
                                        .unwrap();
                                    let group = std::str::from_utf8(&instance.value).unwrap()[1..]
                                        .parse::<usize>()
                                        .unwrap();
                                    assert!(group < groups && !seen[group]);
                                    seen[group] = true;
                                    if request_index != 0 {
                                        assert_eq!(group, position);
                                    }
                                    assert_eq!(row.labels.0.len(), if shape == 3 { 3 } else { 2 });
                                    let expected = format!("g{group:04}");
                                    for label in &*row.labels.0 {
                                        assert!(matches!(
                                            &*label.name,
                                            b"instance" | b"row" | b"alias"
                                        ));
                                        assert_eq!(&*label.value, expected.as_bytes());
                                    }
                                    assert_eq!(row.points.len(), points);
                                    for (tick, point) in row.points.iter().enumerate() {
                                        assert_eq!(point.time_ms, (tick as i64 + 3) * 1000);
                                        let scale = if group % 2 == 0 { 2.0 } else { 4.0 };
                                        let expected = if window {
                                            scale
                                        } else {
                                            scale * (tick + 3) as f64
                                        };
                                        assert_eq!(float_bits(point), expected.to_bits());
                                    }
                                }
                                assert!(seen.into_iter().all(|present| present));
                                assert_eq!(
                                    report.observations.output_samples,
                                    (points * groups) as u64
                                );
                                assert_eq!(
                                    report.observations.memory[MemoryKind::Workspace as usize]
                                        .current,
                                    0
                                );
                                reads.push(report.observations.samples_fetched);
                                provider.assert_closed();
                                drop((report, query));
                                engine.accounting.snapshot().assert_memory_released();
                                complete += 1;
                            }
                            scaling.push((delayed, page, window, request_index, shape, reads));
                        }
                    }
                }
            }
        }
        assert_eq!(complete, 576);
        println!("complete projected-group outcomes={complete}; source reads={scaling:?}");
        // Check growth only after every full numerical and ownership outcome has passed.
        for (delayed, page, window, request, shape, reads) in scaling {
            if !window {
                assert!(
                    reads[3] <= reads[2] * 3,
                    "quadratic projection reads: delayed={delayed} page={page} request={request} shape={shape} reads={reads:?}"
                );
            }
        }
    }

    #[test]
    fn mapped_groups_check_complete_results_before_linear_label_visits() {
        let mut observations = Vec::new();
        for delayed in [false, true] {
            for page in [1, 17] {
                for groups in [1, 4, 16, 64] {
                    let provider = mapped_group_provider(page, groups);
                    let engine = Engine::default();
                    let control = Control::default();
                    let query = engine
                        .compile(
                            b"(sum by(instance)(rate(counter_total[3s]))) > 1",
                            options(delayed),
                            &control,
                        )
                        .unwrap();
                    let (report, reads) =
                        crate::test_storage::observe_label_reads(&control, None, || {
                            query.collect_reported(
                                &provider,
                                QueryRequest::Range {
                                    start_ms: 3000,
                                    end_ms: 5000,
                                    step_ms: 1000,
                                },
                                &control,
                            )
                        });
                    let result = report.result.as_ref().unwrap();
                    assert!(report.annotations.is_empty());
                    assert_eq!(result.series.len(), groups);
                    for (group, row) in result.series.iter().enumerate() {
                        assert_eq!(row.labels.0.len(), 1);
                        assert_eq!(&*row.labels.0[0].name, b"instance");
                        assert_eq!(&*row.labels.0[0].value, format!("g{group:04}").as_bytes());
                        assert_eq!(row.points.len(), 3);
                        for (tick, point) in row.points.iter().enumerate() {
                            assert_eq!(point.time_ms, (tick as i64 + 3) * 1000);
                            assert_eq!(
                                float_bits(point),
                                if group % 2 == 0 { 2.0_f64 } else { 4.0_f64 }.to_bits()
                            );
                        }
                    }
                    assert_eq!(report.observations.output_samples, (3 * groups) as u64);
                    assert_eq!(
                        report.observations.memory[MemoryKind::Workspace as usize].current,
                        0
                    );
                    provider.assert_closed();
                    observations.push((delayed, page, groups, reads));
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
        println!("complete mapped-group outcomes; label reads: {observations:?}");
        // All complete outcomes and ownership checks precede the scaling assertion.
        for (delayed, page, groups, reads) in observations {
            assert!(
                reads <= 200 * groups * 2,
                "unrelated group label replay: delayed={delayed} page={page} groups={groups} reads={reads}"
            );
        }
    }

    #[test]
    fn mapped_group_demand_follows_ordered_maps_and_preserves_clock_fallbacks() {
        let range = QueryRequest::Range {
            start_ms: 3000,
            end_ms: 5000,
            step_ms: 1000,
        };
        let instant = QueryRequest::Instant { time_ms: 3000 };
        let equal = QueryRequest::Range {
            start_ms: 3000,
            end_ms: 3000,
            step_ms: 1000,
        };
        for (expression, request, expected) in [
            ("sum by(instance)(rate(counter_total[3s])) > 1", range, 1),
            ("abs(sum by(instance)(rate(counter_total[3s])))", range, 1),
            ("-(sum by(instance)(rate(counter_total[3s])) > 1)", range, 1),
            (
                "sum(abs(sum by(instance)(rate(counter_total[3s]))))",
                range,
                1,
            ),
            (
                "scalar(abs(sum by(instance)(rate(counter_total[3s]))))",
                range,
                1,
            ),
            (
                "sum by(instance)(rate(counter_total[3s])) * time()",
                range,
                1,
            ),
            ("sum by(instance)(rate(counter_total[3s])) ^ 2", range, 1),
            ("sum by(instance)(rate(counter_total[3s]))", range, 0),
            ("-(sum by(instance)(rate(counter_total[3s])))", range, 0),
            ("sum by(instance)(rate(counter_total[3s])) > 1", instant, 0),
            ("sum by(instance)(rate(counter_total[3s])) > 1", equal, 0),
            (
                "sum by(instance)(rate(counter_total[3s] @ 3)) > 1",
                range,
                0,
            ),
            (
                "sum by(instance)(rate(counter_total[3s])) * scalar(counter_total)",
                range,
                0,
            ),
            (
                "timestamp(sum by(instance)(rate(counter_total[3s])))",
                range,
                0,
            ),
            (
                "label_join(sum by(instance)(counter_total),\"row\",\"/\",\"instance\")",
                range,
                1,
            ),
            (
                "label_join(sum by(instance)(counter_total),\"row\",\"/\",\"instance\")",
                instant,
                1,
            ),
            (
                "label_join(sum by(instance)(counter_total),\"row\",\"/\",\"instance\")",
                equal,
                1,
            ),
            (
                "label_replace(sum by(instance)(rate(counter_total[3s])),\"row\",\"$1\",\"instance\",\"(.*)\")",
                range,
                1,
            ),
            (
                "abs(label_join(sum by(instance)(counter_total),\"row\",\"/\",\"instance\"))",
                instant,
                1,
            ),
            (
                "label_join(sum by(instance)(counter_total @ 3),\"row\",\"/\",\"instance\")",
                range,
                0,
            ),
            (
                "label_join(sum by(instance)(counter_total offset 1s),\"row\",\"/\",\"instance\")",
                range,
                1,
            ),
            (
                "label_join(sum by(instance)(timestamp(counter_total)),\"row\",\"/\",\"instance\")",
                range,
                0,
            ),
            (
                "label_join(sum by(instance)(counter_total*scalar(counter_total)),\"row\",\"/\",\"instance\")",
                range,
                0,
            ),
        ] {
            let provider = mapped_group_provider(17, 4);
            let engine = Engine::default();
            let control = Control::default();
            let query = engine
                .compile(expression.as_bytes(), options(true), &control)
                .unwrap();
            let account = query.execution_accounting();
            let plans = {
                let header = query.header(request).unwrap();
                let prepared = Prepared::new(
                    &query.expression,
                    &query.preprocessing,
                    header,
                    query.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let header = prepared.evaluator_header();
                prepared.activate(header, &control, &account).unwrap();
                let options = query.evaluation_options(header, header.start_ms, &prepared);
                let bounds = crate::query_bounds::find(
                    &query.expression,
                    options,
                    &prepared,
                    &control,
                    &account,
                )
                .unwrap();
                let scope = provider.open(bounds, &control).unwrap();
                let catalog = Catalog::new(
                    &scope,
                    &query.expression,
                    &prepared,
                    options,
                    query.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let rosters = query
                    .prepare_rosters(
                        &catalog,
                        &prepared,
                        bounds,
                        &control,
                        &account,
                        &mut Annotations::default(),
                    )
                    .unwrap();
                (0..query.expression.arena.nodes.len())
                    .filter(|&index| {
                        if let Some(plan) = rosters.group_replay(NodeId(index)) {
                            assert!(
                                !plan.has_completion(),
                                "preparation cannot grant final credit"
                            );
                            true
                        } else {
                            false
                        }
                    })
                    .count()
            };
            provider.assert_closed();
            account.snapshot().assert_memory_released();
            drop((account, query));
            engine.accounting.snapshot().assert_memory_released();
            assert_eq!(plans, expected, "{expression} {request:?}");
        }
    }

    #[test]
    fn mapped_groups_keep_cold_selected_next_clock_and_output_failures() {
        fn acquisitions(input: &FixtureProvider) -> Vec<usize> {
            input
                .series
                .iter()
                .map(|series| series.source.counters.opened.load(Ordering::Relaxed))
                .collect()
        }
        fn drive(
            compiled: &CompiledQuery,
            input: &FixtureProvider,
            stop: Option<(usize, usize, bool)>,
        ) -> (Vec<Vec<Vec<usize>>>, Vec<Vec<usize>>) {
            let control = Control::default();
            let account = compiled.execution_accounting();
            let mut landmarks = Vec::new();
            let mut group_order = Vec::new();
            {
                let header = compiled
                    .header(QueryRequest::Range {
                        start_ms: 1000,
                        end_ms: 2000,
                        step_ms: 1000,
                    })
                    .unwrap();
                let prepared = Prepared::new(
                    &compiled.expression,
                    &compiled.preprocessing,
                    header,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let header = prepared.evaluator_header();
                prepared.activate(header, &control, &account).unwrap();
                let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                let bounds = crate::query_bounds::find(
                    &compiled.expression,
                    options,
                    &prepared,
                    &control,
                    &account,
                )
                .unwrap();
                let scope = input.open(bounds, &control).unwrap();
                let catalog = Catalog::new(
                    &scope,
                    &compiled.expression,
                    &prepared,
                    options,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let rosters = compiled
                    .prepare_rosters(
                        &catalog,
                        &prepared,
                        bounds,
                        &control,
                        &account,
                        &mut Annotations::default(),
                    )
                    .unwrap();
                let plan = (0..compiled.expression.arena.nodes.len())
                    .find_map(|index| rosters.group_replay(NodeId(index)))
                    .unwrap();
                assert!(
                    !plan.has_completion(),
                    "preparation must discard final credit"
                );
                'instants: for instant in 0..2 {
                    let mut machine = Machine::new(
                        &catalog,
                        &compiled.expression,
                        compiled.expression.root,
                        compiled.evaluation_options(header, (instant as i64 + 1) * 1000, &prepared),
                        &control,
                        &account,
                        EvaluationMetadata {
                            prepared: &prepared,
                            rosters: &rosters,
                            timestamp_selectors: &compiled.timestamp_selectors,
                            data_bounds: bounds,
                            annotations: None,
                            binary_preparation: None,
                            histogram_preparation: None,
                            info_preparation: None,
                            count_preparation: None,
                        },
                    );
                    machine.set_step_index(instant as i64);
                    landmarks.push(vec![acquisitions(input)]);
                    group_order.push(Vec::new());
                    let mut outputs = 0;
                    loop {
                        let stopping = stop
                            .is_some_and(|(tick, after, _)| tick == instant && after == outputs);
                        let cancelled = stopping && stop.unwrap().2;
                        if cancelled {
                            control.cancellation.cancel();
                        }
                        let next = machine.next();
                        if stopping {
                            let error = next.unwrap_err();
                            if cancelled {
                                assert!(matches!(
                                    error,
                                    EvaluationError::Interrupted(Interrupted::Cancelled)
                                ));
                            } else {
                                assert!(
                                    matches!(&error, EvaluationError::Storage(StorageError::Provider(bytes))
                                    if &**bytes == b"injected page failure")
                                );
                            }
                            if instant == 0 && outputs == 0 {
                                assert!(
                                    !plan.has_completion(),
                                    "failed full traversal grants no credit"
                                );
                            }
                            drop(error);
                            break 'instants;
                        }
                        let Some(sample) = next.unwrap() else {
                            break;
                        };
                        assert!(
                            plan.has_completion(),
                            "first output requires successful full child Done"
                        );
                        let labels = if compiled.expression.source.starts_with(b"label_") {
                            2
                        } else {
                            1
                        };
                        assert_eq!(sample.labels.0.len(), labels);
                        if labels == 2 {
                            assert_eq!(&*sample.labels.0[1].name, b"row");
                            assert_eq!(sample.labels.0[1].value, sample.labels.0[0].value);
                        }
                        let group = std::str::from_utf8(&sample.labels.0[0].value).unwrap()[1..]
                            .parse::<usize>()
                            .unwrap();
                        let expected =
                            (if group % 2 == 0 { 2.0 } else { 4.0 }) * (instant + 1) as f64;
                        assert!(
                            matches!(sample.value, OwnedValue::Float(value) if value.to_bits() == expected.to_bits())
                        );
                        group_order[instant].push(group);
                        drop(sample);
                        outputs += 1;
                        landmarks[instant].push(acquisitions(input));
                    }
                    assert_eq!(outputs, 4);
                }
            }
            input.assert_closed();
            account.snapshot().assert_memory_released();
            (landmarks, group_order)
        }
        for page in [1, 17, 1024] {
            for delayed in [false, true] {
                for expression in [
                    "sum by(instance)(counter_total) > 0",
                    "label_join(sum by(instance)(counter_total),\"row\",\"/\",\"instance\")",
                    "label_replace(sum by(instance)(counter_total),\"row\",\"$1\",\"instance\",\"(.*)\")",
                ] {
                    let engine = Engine::default();
                    let compiled = engine
                        .compile(expression.as_bytes(), options(delayed), &Control::default())
                        .unwrap();
                    let calibration = mapped_group_provider(page, 4);
                    let (landmarks, group_order) = drive(&compiled, &calibration, None);
                    let cold_nonmember = (0..8)
                        .rfind(|&index| 3 - index / 2 != group_order[0][0])
                        .unwrap();
                    let next_nonmember = (0..8)
                        .rfind(|&index| 3 - index / 2 != group_order[1][0])
                        .unwrap();
                    let (prefix, selected) = landmarks[0]
                        .windows(2)
                        .enumerate()
                        .skip(1)
                        .find_map(|(prefix, pair)| {
                            (0..8)
                                .find(|&index| {
                                    3 - index / 2 == group_order[0][prefix]
                                        && pair[1][index] > pair[0][index]
                                })
                                .map(|index| (prefix, index))
                        })
                        .expect("a later ordered row freshly reads a selected contributor");
                    for (phase, instant, after, target, acquisition) in [
                        (
                            "cold-nonmember",
                            0,
                            0,
                            cold_nonmember,
                            landmarks[0][0][cold_nonmember] + 1,
                        ),
                        (
                            "warm-selected",
                            0,
                            prefix,
                            selected,
                            landmarks[0][prefix][selected] + 1,
                        ),
                        (
                            "next-clock-nonmember",
                            1,
                            0,
                            next_nonmember,
                            landmarks[1][0][next_nonmember] + 1,
                        ),
                    ] {
                        let mut input = mapped_group_provider(page, 4);
                        input.series[target].source.fail_acquisition = Some(acquisition);
                        let observed = drive(&compiled, &input, Some((instant, after, false)));
                        assert_eq!(observed.0.len(), instant + 1);
                        assert_eq!(observed.0[instant].len(), after + 1);
                        assert_eq!(acquisitions(&input)[target], acquisition);
                        println!(
                            "mapped-group expression={expression} phase={phase} page={page} delayed={delayed} instant={instant} outputs={after} target={target} acquisition={acquisition}"
                        );
                    }
                    let input = mapped_group_provider(page, 4);
                    assert_eq!(
                        drive(&compiled, &input, Some((0, prefix, true))).0[0].len(),
                        prefix + 1
                    );
                    for cancel in [false, true] {
                        let input = mapped_group_provider(page, 4);
                        let control = Control::default();
                        let mut sink = RecordingSink {
                            fail_after: (!cancel).then_some(1),
                            cancel: cancel.then(|| control.cancellation.clone()),
                            ..RecordingSink::default()
                        };
                        let report = compiled.execute_reported(
                            &input,
                            QueryRequest::Range {
                                start_ms: 1000,
                                end_ms: 2000,
                                step_ms: 1000,
                            },
                            &control,
                            &mut sink,
                        );
                        if cancel {
                            assert!(matches!(
                                &report.result,
                                Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                                    Interrupted::Cancelled
                                )))
                            ));
                        } else {
                            assert!(
                                matches!(&report.result, Err(ExecutionError::Sink(bytes)) if &**bytes == b"sink failure")
                            );
                            report.assert_retained_callback_error_memory();
                        }
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        input.assert_closed();
                    }
                    drop(compiled);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn histogram_group_contributors_keep_cold_and_selected_failures() {
        fn acquisitions(input: &FixtureProvider) -> Vec<usize> {
            input
                .series
                .iter()
                .map(|series| series.source.counters.opened.load(Ordering::Relaxed))
                .collect()
        }
        fn drive(
            compiled: &CompiledQuery,
            input: &FixtureProvider,
            stop: Option<(usize, bool)>,
        ) -> Vec<Vec<usize>> {
            let control = Control::default();
            let account = compiled.execution_accounting();
            let mut landmarks = Vec::new();
            {
                let header = compiled
                    .header(QueryRequest::Instant { time_ms: 1000 })
                    .unwrap();
                let prepared = Prepared::new(
                    &compiled.expression,
                    &compiled.preprocessing,
                    header,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let header = prepared.evaluator_header();
                prepared.activate(header, &control, &account).unwrap();
                let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                let bounds = crate::query_bounds::find(
                    &compiled.expression,
                    options,
                    &prepared,
                    &control,
                    &account,
                )
                .unwrap();
                let scope = input.open(bounds, &control).unwrap();
                let catalog = Catalog::new(
                    &scope,
                    &compiled.expression,
                    &prepared,
                    options,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let rosters = compiled
                    .prepare_rosters(
                        &catalog,
                        &prepared,
                        bounds,
                        &control,
                        &account,
                        &mut Annotations::default(),
                    )
                    .unwrap();
                let plan = (0..compiled.expression.arena.nodes.len())
                    .find_map(|index| rosters.group_replay(NodeId(index)))
                    .expect("histogram demands grouped contributors");
                assert!(
                    !plan.has_completion(),
                    "preparation must discard contributor credit"
                );
                landmarks.push(acquisitions(input));
                let mut machine = Machine::new(
                    &catalog,
                    &compiled.expression,
                    compiled.expression.root,
                    options,
                    &control,
                    &account,
                    EvaluationMetadata {
                        prepared: &prepared,
                        rosters: &rosters,
                        timestamp_selectors: &compiled.timestamp_selectors,
                        data_bounds: bounds,
                        annotations: None,
                        binary_preparation: None,
                        histogram_preparation: None,
                        info_preparation: None,
                        count_preparation: None,
                    },
                );
                // Exercise the call body before API output-head preparation buffers its results.
                machine.bypass_root_order();
                let mut outputs = 0;
                loop {
                    let stopping = stop.is_some_and(|(after, _)| after == outputs);
                    let cancelled = stopping && stop.unwrap().1;
                    if cancelled {
                        control.cancellation.cancel();
                    }
                    let next = machine.next();
                    if stopping {
                        assert_eq!(plan.has_completion(), outputs != 0);
                        let error = next.unwrap_err();
                        if cancelled {
                            assert!(matches!(
                                error,
                                EvaluationError::Interrupted(Interrupted::Cancelled)
                            ));
                        } else {
                            assert!(
                                matches!(&error, EvaluationError::Storage(StorageError::Provider(bytes))
                                if &**bytes == b"injected page failure")
                            );
                        }
                        drop(error);
                        break;
                    }
                    let Some(sample) = next.unwrap() else {
                        break;
                    };
                    assert!(
                        plan.has_completion(),
                        "first sample follows successful complete input"
                    );
                    assert!(matches!(sample.value, OwnedValue::Float(value) if value.is_finite()));
                    drop(sample);
                    outputs += 1;
                    landmarks.push(acquisitions(input));
                }
            }
            input.assert_closed();
            account.snapshot().assert_memory_released();
            landmarks
        }
        let provider = |page| {
            let mut input = FixtureProvider::new(1, page, 8);
            for (index, series) in input.series.iter_mut().enumerate() {
                series.labels = vec![
                    (b"__name__".to_vec(), b"counter_total".to_vec()),
                    (b"instance".to_vec(), (index / 4).to_string().into_bytes()),
                    (
                        b"le".to_vec(),
                        if index % 4 < 2 {
                            b"1".as_slice()
                        } else {
                            b"+Inf".as_slice()
                        }
                        .to_vec(),
                    ),
                    (b"member".to_vec(), (index % 2).to_string().into_bytes()),
                ];
                series.source.counters = Default::default();
            }
            input
        };
        let child = "sum by(instance,le)(counter_total)";
        for (expression, outputs) in [
            (format!("histogram_quantile(.5,{child})"), 2),
            (format!("histogram_fraction(.25,.75,{child})"), 2),
            (format!("histogram_quantiles({child},\"q\",.25,.75)"), 4),
        ] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let mut settings = EngineOptions {
                        delayed_name_removal: delayed,
                        ..EngineOptions::default()
                    };
                    settings.parser.experimental_functions = true;
                    let compiled = engine
                        .compile(expression.as_bytes(), settings, &control)
                        .unwrap();
                    let calibration = provider(page);
                    let landmarks = drive(&compiled, &calibration, None);
                    assert_eq!(landmarks.len(), outputs + 1);
                    let (prefix, selected) = landmarks
                        .windows(2)
                        .enumerate()
                        .skip(1)
                        .find_map(|(prefix, rows)| {
                            (0..8)
                                .rev()
                                .find(|index| rows[1][*index] > rows[0][*index])
                                .map(|selected| (prefix, selected))
                        })
                        .expect("a later histogram result freshly reads a selected contributor");
                    for (phase, after, target, acquisition) in [
                        ("cold-nonmember", 0, 7, landmarks[0][7] + 1),
                        (
                            "warm-selected",
                            prefix,
                            selected,
                            landmarks[prefix][selected] + 1,
                        ),
                    ] {
                        let mut input = provider(page);
                        input.series[target].source.fail_acquisition = Some(acquisition);
                        let observed = drive(&compiled, &input, Some((after, false)));
                        assert_eq!(observed.len(), after + 1);
                        assert_eq!(acquisitions(&input)[target], acquisition);
                        println!(
                            "{{\"histogram_contributor_phase\":\"{phase}\",\"expression\":{expression:?},\"page_size\":{page},\"delayed\":{delayed},\"selected\":{target},\"acquisition\":{acquisition},\"evaluated_samples\":{after}}}"
                        );
                    }
                    let input = provider(page);
                    assert_eq!(
                        drive(&compiled, &input, Some((prefix, true))).len(),
                        prefix + 1
                    );
                    for cancel in [false, true] {
                        let input = provider(page);
                        let execution = Control::default();
                        let mut sink = RecordingSink {
                            fail_after: (!cancel).then_some(1),
                            cancel: cancel.then(|| execution.cancellation.clone()),
                            ..RecordingSink::default()
                        };
                        let report = compiled.execute_reported(
                            &input,
                            QueryRequest::Instant { time_ms: 1000 },
                            &execution,
                            &mut sink,
                        );
                        if cancel {
                            assert!(matches!(
                                &report.result,
                                Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                                    Interrupted::Cancelled
                                )))
                            ));
                        } else {
                            assert!(
                                matches!(&report.result, Err(ExecutionError::Sink(bytes)) if &**bytes == b"sink failure")
                            );
                            report.assert_retained_callback_error_memory();
                        }
                        assert!(sink.begun && sink.aborted && !sink.committed);
                        input.assert_closed();
                    }
                    drop(compiled);
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn ordered_histogram_streaming_keeps_acquisition_and_filter_phases() {
        #[derive(Clone, Copy)]
        enum Restriction {
            All,
            One(usize),
            Ordinals(&'static [usize]),
            Contributors(usize),
        }
        struct Trace {
            landmarks: Vec<Vec<usize>>,
            ordinals: Vec<usize>,
            final_acquisitions: Vec<usize>,
        }
        fn acquisitions(input: &FixtureProvider) -> Vec<usize> {
            input
                .series
                .iter()
                .map(|row| row.source.counters.opened.load(Ordering::Relaxed))
                .collect()
        }
        fn drive(
            compiled: &CompiledQuery,
            input: &FixtureProvider,
            restriction: Restriction,
            eligible: bool,
            stop: Option<(usize, bool)>,
            truncate: bool,
        ) -> Trace {
            let control = Control::default();
            let account = compiled.execution_accounting();
            let mut trace = Trace {
                landmarks: Vec::new(),
                ordinals: Vec::new(),
                final_acquisitions: Vec::new(),
            };
            {
                let header = compiled
                    .header(QueryRequest::Range {
                        start_ms: 1000,
                        end_ms: 1001,
                        step_ms: 1000,
                    })
                    .unwrap();
                let prepared = Prepared::new(
                    &compiled.expression,
                    &compiled.preprocessing,
                    header,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let header = prepared.evaluator_header();
                prepared.activate(header, &control, &account).unwrap();
                let options = compiled.evaluation_options(header, header.start_ms, &prepared);
                let bounds = crate::query_bounds::find(
                    &compiled.expression,
                    options,
                    &prepared,
                    &control,
                    &account,
                )
                .unwrap();
                let scope = input.open(bounds, &control).unwrap();
                let catalog = Catalog::new(
                    &scope,
                    &compiled.expression,
                    &prepared,
                    options,
                    compiled.options.no_step_subquery_interval_ms,
                    &control,
                    &account,
                )
                .unwrap();
                let rosters = compiled
                    .prepare_rosters(
                        &catalog,
                        &prepared,
                        bounds,
                        &control,
                        &account,
                        &mut Annotations::default(),
                    )
                    .unwrap();
                assert_eq!(
                    rosters
                        .histogram(compiled.expression.root)
                        .unwrap()
                        .streams_ordered(),
                    eligible
                );
                let contributors = if matches!(restriction, Restriction::Contributors(_)) {
                    let mut builder = crate::aggregate_replay::Builder::new(
                        compiled.expression.root,
                        true,
                        &account,
                    );
                    builder.record(0, 1, &control, &account).unwrap();
                    let plan = builder.finish(2, &control, &account).unwrap();
                    let key = crate::vector_matching::ReplayKey::new(
                        options,
                        0,
                        prepared.lookback_ns(options.lookback_ms),
                        bounds,
                    );
                    plan.complete(key, &control, &account).unwrap();
                    let Restriction::Contributors(group) = restriction else {
                        unreachable!()
                    };
                    assert!(
                        plan.activate(
                            crate::evaluator::RowFilter::One(group),
                            key,
                            &control,
                            &account
                        )
                        .unwrap()
                    );
                    Some(plan)
                } else {
                    None
                };
                let mut machine = Machine::new(
                    &catalog,
                    &compiled.expression,
                    compiled.expression.root,
                    options,
                    &control,
                    &account,
                    EvaluationMetadata {
                        prepared: &prepared,
                        rosters: &rosters,
                        timestamp_selectors: &compiled.timestamp_selectors,
                        data_bounds: bounds,
                        annotations: None,
                        binary_preparation: None,
                        histogram_preparation: None,
                        info_preparation: None,
                        count_preparation: None,
                    },
                );
                match restriction {
                    Restriction::All => (),
                    Restriction::One(ordinal) => machine.restrict_one(ordinal),
                    Restriction::Ordinals(ordinals) => machine.restrict(ordinals),
                    Restriction::Contributors(_) => {
                        machine.restrict_contributors(contributors.as_ref().unwrap())
                    }
                }
                trace.landmarks.push(acquisitions(input));
                loop {
                    let stopping = stop.is_some_and(|(after, _)| after == trace.ordinals.len());
                    let cancelled = stopping && stop.unwrap().1;
                    if cancelled {
                        control.cancellation.cancel();
                    }
                    let next = machine.next();
                    if stopping {
                        let error = next.unwrap_err();
                        if cancelled {
                            assert!(matches!(
                                error,
                                EvaluationError::Interrupted(Interrupted::Cancelled)
                            ));
                        } else {
                            assert!(
                                matches!(&error, EvaluationError::Storage(StorageError::Provider(bytes)) if &**bytes == b"injected page failure")
                            );
                        }
                        break;
                    }
                    let Some(sample) = next.unwrap() else {
                        break;
                    };
                    assert_eq!(sample.source_time_ms, 1000);
                    assert!(matches!(sample.value, OwnedValue::Float(value) if value.is_finite()));
                    assert_eq!(
                        sample
                            .labels
                            .get_checked(b"instance", &account, &control)
                            .unwrap(),
                        if sample.ordinal == 0 { b"a" } else { b"b" }
                    );
                    trace.ordinals.push(sample.ordinal);
                    drop(sample);
                    trace.landmarks.push(acquisitions(input));
                    if truncate {
                        break;
                    }
                }
                trace.final_acquisitions = acquisitions(input);
            }
            input.assert_closed();
            account.snapshot().assert_memory_released();
            trace
        }
        fn point<const VALUE: u64>(index: usize) -> crate::value::Sample {
            crate::value::Sample {
                time_ms: (index as i64 + 1) * 1000,
                start_time_ms: 0,
                value: crate::value::SampleValue::Float(VALUE as f64),
            }
        }
        fn quantile(index: usize) -> crate::value::Sample {
            let mut sample = point::<1>(index);
            sample.value = crate::value::SampleValue::Float(0.25);
            sample
        }
        fn native(index: usize) -> crate::value::Sample {
            let mut sample = point::<1>(index);
            sample.value =
                crate::value::SampleValue::FloatHistogram(crate::histogram::FloatHistogram {
                    zero_threshold: 1.0,
                    zero_count: 2.0,
                    count: 2.0,
                    ..Default::default()
                });
            sample
        }
        let provider = |page, histogram| {
            let count = if histogram { 2 } else { 4 };
            let mut input = FixtureProvider::new(3, page, count + 1);
            for (index, row) in input.series.iter_mut().enumerate() {
                row.source.counters = Default::default();
                if index == count {
                    row.labels = vec![(b"__name__".to_vec(), b"q".to_vec())];
                    row.source.sample = quantile;
                } else {
                    row.labels = vec![
                        (b"__name__".to_vec(), b"counter_total".to_vec()),
                        (
                            b"instance".to_vec(),
                            if index < count / 2 { b"a" } else { b"b" }.to_vec(),
                        ),
                    ];
                    if histogram {
                        row.source.sample = native;
                    } else {
                        row.labels.push((
                            b"le".to_vec(),
                            if index % 2 == 0 {
                                b"1".as_slice()
                            } else {
                                b"+Inf".as_slice()
                            }
                            .to_vec(),
                        ));
                        row.source.sample = if index % 2 == 0 {
                            point::<1>
                        } else {
                            point::<2>
                        };
                    }
                }
            }
            input
        };
        for function in [
            "histogram_quantile(.5,counter_total)",
            "histogram_fraction(0,1,counter_total)",
        ] {
            for page in [1, 17, 1024] {
                for delayed in [false, true] {
                    let engine = Engine::default();
                    let control = Control::default();
                    let settings = EngineOptions {
                        delayed_name_removal: delayed,
                        ..EngineOptions::default()
                    };
                    let compiled = engine
                        .compile(function.as_bytes(), settings, &control)
                        .unwrap();
                    for histogram in [false, true] {
                        let input = provider(page, histogram);
                        let normal = drive(&compiled, &input, Restriction::All, true, None, false);
                        assert_eq!(normal.ordinals, [0, 1]);
                        let selected = if histogram { 1 } else { 3 };
                        assert!(normal.landmarks[2][selected] > normal.landmarks[1][selected]);
                        for (after, target, acquisition) in [
                            (0, selected, normal.landmarks[0][selected] + 1),
                            (1, selected, normal.landmarks[1][selected] + 1),
                        ] {
                            let mut input = provider(page, histogram);
                            input.series[target].source.fail_acquisition = Some(acquisition);
                            let trace = drive(
                                &compiled,
                                &input,
                                Restriction::All,
                                true,
                                Some((after, false)),
                                false,
                            );
                            assert_eq!(trace.ordinals.len(), after);
                            assert_eq!(trace.final_acquisitions[target], acquisition);
                        }
                        let input = provider(page, histogram);
                        assert_eq!(
                            drive(
                                &compiled,
                                &input,
                                Restriction::All,
                                true,
                                Some((1, true)),
                                false
                            )
                            .ordinals,
                            [0]
                        );
                        let input = provider(page, histogram);
                        assert_eq!(
                            drive(&compiled, &input, Restriction::All, true, None, true).ordinals,
                            [0]
                        );
                        for restriction in [
                            Restriction::One(1),
                            Restriction::Ordinals(&[1]),
                            Restriction::Contributors(0),
                        ] {
                            let input = provider(page, histogram);
                            assert_eq!(
                                drive(&compiled, &input, restriction, true, None, false).ordinals,
                                [1]
                            );
                        }
                        for restriction in [
                            Restriction::One(99),
                            Restriction::Ordinals(&[]),
                            Restriction::Contributors(1),
                        ] {
                            let input = provider(page, histogram);
                            let empty = drive(&compiled, &input, restriction, true, None, false);
                            assert!(empty.ordinals.is_empty());
                            assert_eq!(empty.landmarks[0], empty.final_acquisitions);
                        }
                    }
                    let mut reversed = provider(page, true);
                    reversed.series.swap(0, 1);
                    assert_eq!(
                        drive(&compiled, &reversed, Restriction::All, false, None, false).ordinals,
                        [0, 1]
                    );
                    let dynamic = function
                        .replace("(.5,", "(scalar(q),")
                        .replace("(0,1,", "(scalar(q),1,");
                    let dynamic = engine
                        .compile(dynamic.as_bytes(), settings, &control)
                        .unwrap();
                    let input = provider(page, false);
                    let trace = drive(&dynamic, &input, Restriction::All, false, None, false);
                    assert_eq!(trace.ordinals, [0, 1]);
                    assert!(trace.landmarks[2][4] > trace.landmarks[1][4]);
                    let mut input = provider(page, false);
                    input.series[4].source.fail_acquisition = Some(trace.landmarks[1][4] + 1);
                    drive(
                        &dynamic,
                        &input,
                        Restriction::All,
                        false,
                        Some((1, false)),
                        false,
                    );
                    drop((compiled, dynamic));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

    #[test]
    fn histogram_call_argument_failure_aborts_and_releases_owners() {
        for source in [
            "histogram_quantile(0.5,sum_over_time(counter_total[1000000s]))",
            "histogram_fraction(0.25,0.75,sum_over_time(counter_total[1000000s]))",
            "histogram_quantiles(sum_over_time(counter_total[1000000s]),\"q\",0.25,0.75)",
        ] {
            let mut provider = FixtureProvider::new(100, 17, 2);
            for (index, series) in provider.series.iter_mut().enumerate() {
                series.labels[1].1 = b"same".to_vec();
                series.labels.push((
                    b"le".to_vec(),
                    if index == 0 {
                        b"1".to_vec()
                    } else {
                        b"+Inf".to_vec()
                    },
                ));
            }
            provider.series[1].source.fail_page = Some(1);
            let engine = Engine::default();
            let control = Control::default();
            let mut settings = EngineOptions::default();
            settings.parser.experimental_functions = true;
            let query = engine
                .compile(source.as_bytes(), settings, &control)
                .unwrap();
            let mut sink = RecordingSink::default();
            let error = query
                .execute(
                    &provider,
                    QueryRequest::Instant { time_ms: 100_000 },
                    &control,
                    &mut sink,
                )
                .unwrap_err();
            assert!(matches!(
                error,
                ExecutionError::Evaluation(EvaluationError::Storage(_))
            ));
            assert!(sink.begun && sink.aborted && !sink.committed);
            provider.assert_closed();
            drop(error);
            drop(query);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn histogram_call_cancellation_during_count_replay_releases_every_owner() {
        use crate::storage::{Cancellation, Interrupted};
        thread_local! {
            static GATE: std::cell::RefCell<Option<(Cancellation, usize)>> = const { std::cell::RefCell::new(None) };
        }
        fn sample(index: usize) -> crate::value::Sample {
            GATE.with_borrow_mut(|gate| {
                if let Some((cancellation, reads)) = gate {
                    *reads += 1;
                    if *reads == 5 {
                        cancellation.cancel();
                    }
                }
            });
            crate::test_storage::counter(index)
        }
        for source in [
            "histogram_quantile(0.5,counter_total)",
            "histogram_fraction(0.25,0.75,counter_total)",
            "histogram_quantiles(counter_total,\"q\",0.25,0.75)",
        ] {
            let mut provider = FixtureProvider::new(1, 1, 2);
            for (index, series) in provider.series.iter_mut().enumerate() {
                series.labels[1].1 = b"same".to_vec();
                series.labels.push((
                    b"le".to_vec(),
                    if index == 0 {
                        b"1".to_vec()
                    } else {
                        b"+Inf".to_vec()
                    },
                ));
                series.source.sample = sample;
            }
            let engine = Engine::default();
            let control = Control::default();
            let mut settings = EngineOptions::default();
            settings.parser.experimental_functions = true;
            let query = engine
                .compile(source.as_bytes(), settings, &control)
                .unwrap();
            // Two descriptor reads and two classification reads precede the first count request.
            GATE.with_borrow_mut(|gate| *gate = Some((control.cancellation.clone(), 0)));
            let mut sink = RecordingSink::default();
            let outcome = query.execute(
                &provider,
                QueryRequest::Instant { time_ms: 1000 },
                &control,
                &mut sink,
            );
            let reads = GATE.with_borrow_mut(|gate| gate.take().unwrap().1);
            assert_eq!(reads, 5);
            let error = outcome.unwrap_err();
            assert!(matches!(
                error,
                ExecutionError::Evaluation(EvaluationError::Interrupted(Interrupted::Cancelled))
                    | ExecutionError::Evaluation(EvaluationError::Storage(
                        StorageError::Interrupted(Interrupted::Cancelled)
                    ))
            ));
            assert!(sink.begun && sink.aborted && !sink.committed);
            provider.assert_closed();
            drop(error);
            drop(query);
            engine.accounting.snapshot().assert_memory_released();
        }
    }

    #[test]
    fn plural_quantiles_keep_duplicate_occurrences_until_the_source_cleanup_phase() {
        let call = "histogram_quantiles(counter_total,\"q\",0.25,0.75,0.25,0.75)";
        for delayed in [false, true] {
            for parent in ["", "sum by(q)", "topk(1,"] {
                let source = match parent {
                    "" => call.to_owned(),
                    "sum by(q)" => format!("{parent}({call})"),
                    _ => format!("{parent}{call})"),
                };
                let mut provider = FixtureProvider::new(2, 1, 2);
                for (index, series) in provider.series.iter_mut().enumerate() {
                    series.labels[1].1 = b"same".to_vec();
                    series.labels.push((
                        b"le".to_vec(),
                        if index == 0 {
                            b"1".to_vec()
                        } else {
                            b"+Inf".to_vec()
                        },
                    ));
                }
                let engine = Engine::default();
                let account = engine.accounting.clone();
                let control = Control::default();
                let mut settings = options(delayed);
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                drop(engine);
                let outcome =
                    query.collect(&provider, QueryRequest::Instant { time_ms: 2000 }, &control);
                if !delayed || parent.is_empty() {
                    assert!(
                        is_duplicate(&outcome.unwrap_err()),
                        "{source} delayed {delayed}"
                    );
                } else {
                    let (result, _) = outcome.unwrap();
                    let expected: &[f64] = if parent == "sum by(q)" {
                        &[0.5, 1.5]
                    } else {
                        &[0.75]
                    };
                    assert_eq!(result.series.len(), expected.len(), "{source}");
                    for (series, value) in result.series.iter().zip(expected) {
                        assert_eq!(float_bits(&series.points[0]), value.to_bits(), "{source}");
                    }
                    drop(result);
                }
                provider.assert_closed();
                drop(query);
                account.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn empty_plural_destination_errors_only_when_reserved_removal_visits_it() {
        let call = "histogram_quantiles(counter_total,\"\",0.25,0.75)";
        for delayed in [false, true] {
            for (source, removes_names, expected) in [
                (call.to_owned(), delayed, vec![0.25_f64, 0.75]),
                (format!("sum({call})"), false, vec![1.0]),
                (format!("sum(-({call}))"), !delayed, vec![-1.0]),
                (format!("sum(abs({call}))"), !delayed, vec![1.0]),
            ] {
                let mut provider = FixtureProvider::new(2, 1, 2);
                for (index, series) in provider.series.iter_mut().enumerate() {
                    series.labels[1].1 = b"same".to_vec();
                    series.labels.push((
                        b"le".to_vec(),
                        if index == 0 {
                            b"1".to_vec()
                        } else {
                            b"+Inf".to_vec()
                        },
                    ));
                }
                let engine = Engine::default();
                let control = Control::default();
                let mut settings = options(delayed);
                settings.parser.experimental_functions = true;
                let query = engine
                    .compile(source.as_bytes(), settings, &control)
                    .unwrap();
                let outcome =
                    query.collect(&provider, QueryRequest::Instant { time_ms: 2000 }, &control);
                if removes_names {
                    let error = outcome.unwrap_err();
                    let ExecutionError::Evaluation(EvaluationError::WrappedRuntime(message)) =
                        &error
                    else {
                        panic!("unexpected empty-name failure: {error:?}");
                    };
                    assert_eq!(
                        &**message,
                        b"unexpected error: runtime error: index out of range [0] with length 0"
                    );
                    drop(error);
                } else {
                    let (result, _) = outcome.unwrap();
                    assert_eq!(result.series.len(), expected.len(), "{source}");
                    for (series, value) in result.series.iter().zip(expected) {
                        assert_eq!(float_bits(&series.points[0]), value.to_bits(), "{source}");
                    }
                    if source == call {
                        assert!(
                            result
                                .series
                                .iter()
                                .all(|series| series.labels.0[0].name.is_empty())
                        );
                    }
                    drop(result);
                }
                provider.assert_closed();
                drop(query);
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn subquery_history_keeps_constant_workspace_for_fixed_float_and_native_children() {
        fn native(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            sample.value =
                crate::value::SampleValue::FloatHistogram(crate::histogram::FloatHistogram {
                    count: 1.0,
                    zero_count: 1.0,
                    sum: 1.0,
                    ..crate::histogram::FloatHistogram::default()
                });
            sample
        }
        for page_size in [1, 17, 1024] {
            for histogram in [false, true] {
                let mut peaks = vec![];
                for count in [1024, 100_000] {
                    let engine = Engine::default();
                    let mut provider = FixtureProvider::new(1, page_size, 1);
                    if histogram {
                        provider.series[0].source.sample = native;
                    }
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("count_over_time((counter_total @1)[{count}s:1s])").as_bytes(),
                            EngineOptions::default(),
                            &control,
                        )
                        .unwrap();
                    let (result, observed) = query
                        .collect(
                            &provider,
                            QueryRequest::Instant {
                                time_ms: count as i64 * 1000,
                            },
                            &control,
                        )
                        .unwrap();
                    assert_eq!(result.series.len(), 1);
                    assert_eq!(
                        float_bits(&result.series[0].points[0]),
                        (count as f64).to_bits()
                    );
                    peaks.push(observed.memory[MemoryKind::Workspace as usize].peak);
                    assert_eq!(
                        provider.series[0]
                            .source
                            .counters
                            .peak
                            .load(Ordering::Relaxed),
                        1
                    );
                    assert_eq!(
                        observed.memory[MemoryKind::ProviderHeld as usize].current,
                        0
                    );
                    provider.assert_closed();
                    drop((result, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
                assert_eq!(peaks[0], peaks[1]);
            }
        }
    }

    #[test]
    fn subquery_replays_distinct_raw_history_without_retaining_either_timeline() {
        fn seek_index(time_ms: i64) -> usize {
            usize::try_from(time_ms.saturating_sub(1).max(0) / 1000).unwrap()
        }
        for body in ["counter_total", "(counter_total*1)"] {
            let mut peaks = vec![];
            for count in [1024, 100_000] {
                let engine = Engine::default();
                let mut provider = FixtureProvider::new(count, 1, 1);
                provider.series[0].source.seek_index = Some(seek_index);
                let control = Control::default();
                let query = engine
                    .compile(
                        format!("count_over_time({body}[{count}s:1s])").as_bytes(),
                        EngineOptions {
                            lookback_ms: 1,
                            ..EngineOptions::default()
                        },
                        &control,
                    )
                    .unwrap();
                let (result, observed) = query
                    .collect(
                        &provider,
                        QueryRequest::Instant {
                            time_ms: count as i64 * 1000,
                        },
                        &control,
                    )
                    .unwrap();
                assert_eq!(result.series.len(), 1);
                assert_eq!(
                    float_bits(&result.series[0].points[0]),
                    (count as f64).to_bits()
                );
                assert!(observed.samples_fetched >= count as u64);
                assert!(observed.samples_fetched <= 8 * count as u64 + 16);
                assert!(observed.work <= 5000 * count as u64);
                assert_eq!(
                    observed.samples_fetched,
                    provider.series[0]
                        .source
                        .counters
                        .samples_returned
                        .load(Ordering::Relaxed) as u64
                );
                assert_eq!(
                    provider.series[0]
                        .source
                        .counters
                        .peak
                        .load(Ordering::Relaxed),
                    1
                );
                assert_eq!(
                    observed.memory[MemoryKind::ProviderHeld as usize].current,
                    0
                );
                peaks.push((
                    observed.memory[MemoryKind::Workspace as usize].peak,
                    observed.memory[MemoryKind::ProviderHeld as usize].peak,
                ));
                provider.assert_closed();
                drop((result, query));
                engine.accounting.snapshot().assert_memory_released();
            }
            assert_eq!(peaks[0], peaks[1]);
        }
    }

    #[test]
    fn direct_subquery_streams_growing_history_without_retaining_output() {
        for body in ["vector(1)", "counter_total", "(counter_total*1)"] {
            let mut peaks = vec![];
            for count in [1024, 100_000] {
                let engine = Engine::default();
                let provider =
                    FixtureProvider::new(if body == "vector(1)" { 1 } else { count }, 1, 1);
                let control = Control::default();
                let query = engine
                    .compile(
                        format!("{body}[{count}s:1s]").as_bytes(),
                        EngineOptions::default(),
                        &control,
                    )
                    .unwrap();
                let mut sink = RecordingSink::default();
                let report = query.execute_reported(
                    &provider,
                    QueryRequest::Instant {
                        time_ms: count as i64 * 1000,
                    },
                    &control,
                    &mut sink,
                );
                report.result.as_ref().unwrap();
                assert_eq!(sink.chunks, count);
                assert!(sink.begun && sink.committed && !sink.aborted);
                assert_eq!(report.observations.output_samples, count as u64);
                assert!(report.observations.samples_fetched <= 4 * count as u64 + 16);
                assert!(report.observations.work <= 5000 * count as u64);
                assert_eq!(
                    report.observations.memory[MemoryKind::Result as usize].peak,
                    0
                );
                peaks.push(report.observations.memory[MemoryKind::Workspace as usize].peak);
                provider.assert_closed();
                drop((report, query, sink));
                engine.accounting.snapshot().assert_memory_released();
            }
            assert_eq!(peaks[0], peaks[1]);
        }
    }

    #[test]
    fn direct_subquery_keeps_one_raw_page_as_series_cardinality_grows() {
        for body in ["counter_total", "(counter_total*1)"] {
            for page_size in [1, 17, 1024] {
                let mut peaks = vec![];
                for metrics in [2, 257] {
                    let engine = Engine::default();
                    let mut provider = FixtureProvider::new(64, page_size, metrics);
                    let counters =
                        std::sync::Arc::new(crate::test_storage::CursorCounts::default());
                    for series in &mut provider.series {
                        series.source.counters = counters.clone();
                    }
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("{body}[64s:1s]").as_bytes(),
                            EngineOptions::default(),
                            &control,
                        )
                        .unwrap();
                    let mut sink = RecordingSink::default();
                    let report = query.execute_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 64000 },
                        &control,
                        &mut sink,
                    );
                    report.result.as_ref().unwrap();
                    assert_eq!(sink.chunks, metrics * 64);
                    assert_eq!(counters.peak.load(Ordering::Relaxed), 1);
                    assert_eq!(counters.active.load(Ordering::Relaxed), 0);
                    assert_eq!(
                        report.observations.samples_fetched,
                        counters.samples_returned.load(Ordering::Relaxed) as u64
                    );
                    peaks.push(report.observations.memory[MemoryKind::ProviderHeld as usize].peak);
                    provider.assert_closed();
                    drop((report, query, sink));
                    engine.accounting.snapshot().assert_memory_released();
                }
                assert_eq!(peaks[0], peaks[1]);
            }
        }
    }

    #[test]
    fn direct_subquery_aborts_provisional_output_on_failure_cancellation_and_panic() {
        for body in ["vector(1)", "counter_total", "(counter_total*1)"] {
            for phase in 0..3 {
                let engine = Engine::default();
                let provider =
                    FixtureProvider::new(if body == "vector(1)" { 1 } else { 100 }, 1, 1);
                let control = Control::default();
                let query = engine
                    .compile(
                        format!("{body}[100s:1s]").as_bytes(),
                        EngineOptions::default(),
                        &control,
                    )
                    .unwrap();
                let mut sink = RecordingSink {
                    fail_after: (phase == 0).then_some(2),
                    cancel: (phase == 1).then(|| control.cancellation.clone()),
                    panic_after: (phase == 2).then_some(2),
                    ..RecordingSink::default()
                };
                let report = query.execute_reported(
                    &provider,
                    QueryRequest::Instant { time_ms: 100000 },
                    &control,
                    &mut sink,
                );
                match (&report.result, phase) {
                    (Err(ExecutionError::Sink(bytes)), 0) => assert_eq!(&**bytes, b"sink failure"),
                    (
                        Err(ExecutionError::Evaluation(EvaluationError::Interrupted(
                            crate::storage::Interrupted::Cancelled,
                        ))),
                        1,
                    ) => (),
                    (Err(ExecutionError::Internal), 2) => (),
                    _ => panic!("derived output failure phase: {:?}", report.result),
                }
                assert_eq!(sink.chunks, 2);
                assert!(sink.begun && sink.aborted && !sink.committed);
                assert_eq!(
                    report.observations.output_samples,
                    if phase == 1 { 2 } else { 1 }
                );
                provider.assert_closed();
                report.assert_retained_callback_error_memory();
                drop((report, query, sink));
                engine.accounting.snapshot().assert_memory_released();
            }
        }
    }

    #[test]
    fn derived_changes_and_resets_report_reached_ties_after_child_acquisition() {
        fn native(index: usize) -> crate::value::Sample {
            let mut sample = crate::test_storage::counter(index);
            sample.value = crate::value::SampleValue::FloatHistogram(
                crate::histogram::FloatHistogram::default(),
            );
            sample
        }
        for page_size in [1, 17, 1024] {
            for function in ["changes", "resets"] {
                for failure in [false, true] {
                    let engine = Engine::default();
                    let mut provider = FixtureProvider::new(4, page_size, 2);
                    for (series, name) in provider.series.iter_mut().zip([b"a", b"b"]) {
                        series.labels = vec![(b"__name__".to_vec(), name.to_vec())];
                    }
                    provider.series[1].source.sample = native;
                    if failure {
                        provider.series[1].source.fail_page = Some(0);
                    }
                    let control = Control::default();
                    let query = engine
                        .compile(
                            format!("{function}((-{{__name__=~\"a|b\"}})[4s:1s])").as_bytes(),
                            EngineOptions::default(),
                            &control,
                        )
                        .unwrap();
                    let report = query.collect_reported(
                        &provider,
                        QueryRequest::Instant { time_ms: 4000 },
                        &control,
                    );
                    if failure {
                        let Err(ExecutionError::Evaluation(EvaluationError::Storage(
                            StorageError::Provider(bytes),
                        ))) = &report.result
                        else {
                            panic!("child acquisition precedes derived helper");
                        };
                        assert_eq!(&**bytes, b"injected page failure");
                    } else {
                        let Err(ExecutionError::Evaluation(EvaluationError::Invalid(message))) =
                            &report.result
                        else {
                            panic!("reached source nonadvancing merge");
                        };
                        assert_eq!(
                            *message,
                            if function == "changes" {
                                "changes() cannot advance past equal float and histogram timestamps"
                            } else {
                                "resets() cannot advance past equal float and histogram timestamps"
                            }
                        );
                    }
                    assert_eq!(report.observations.output_samples, 0);
                    provider.assert_closed();
                    report.assert_retained_callback_error_memory();
                    drop((report, query));
                    engine.accounting.snapshot().assert_memory_released();
                }
            }
        }
    }

